SELECT 'moj-all-verified-judgments-review-002-chunk-099' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"b2b6e305-8989-5e21-a284-70b9d0a43ecd","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة -تستر -هروب من الفرقة القابضة -اعتراف حتقيق ا -تعزير بالسجن واملنع من السفر - عدم التقيد بالوصف الوارد يف الئحة الدعوى وإعطاء المحكمة الفعل الوصف الذي يستحقه .","document_number":"34198256","case_number":"34167081","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/27","year":"1434","subject":"مخدرات -حيازة حبوب محظورة -تستر -هروب من الفرقة القابضة -اعتراف حتقيق ا -تعزير بالسجن واملنع من السفر - عدم التقيد بالوصف الوارد يف الئحة الدعوى وإعطاء المحكمة الفعل الوصف الذي يستحقه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34198256:‬تاريخه‪1434/4/27:‬هـ‬\n                        ‫رقم الدعوى‪34167081:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34244052‬تاريخه‪1434/06/18 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة حبــوب محظــورة ‪ -‬تســتر‪ -‬هــروب مــن الفرقــة‬\n      ‫القابضــة ‪ -‬اعتــراف حتقيق ـ ًا‪ -‬تعزيــر بالســجن واملنــع مــن الســفر ‪-‬‬\n      ‫عــدم التقيــد بالوصــف الــوارد يف الئحــة الدعــوى وإعطــاء احملكمــة‬\n                                           ‫الفعــل الوصــف الــذي يســتحقه ‪.‬‬\n\n\n\n                      ‫املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n      ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه بحيــازة احلبــوب احملظــورة‬\n      ‫لغيــر قصــد الترويــج أو التعاطــي أو االســتخدام وتســتره علــى مصــدر‬\n      ‫احلبــوب وهروبــه مــن الفرقــة القابضــة‪ ،‬وطلــب املدعــي العــام إثبــات مــا‬\n      ‫أســند إليــه واحلكــم عليــه بالعقوبــة الــواردة يف املــادة (‪ )39‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة ومنعــه مــن الســفر وعقوبــة‬\n      ‫تعزيريــة لقــاء تســتره علــى مصــدر املخــدرات وهروبــه مــن الفرقــة‬\n      ‫القابضــة ‪ ،‬مت القبــض علــى املدعــى عليــه حيــث كان عاكسـ ًا للســير‬\n      ‫علــى ســيارته فتــم اســتيقافه فرمــى كيــس بداخلــه (‪ )14‬حبــة يشــتبه‬\n      ‫أن تكــون محظــورة ثــم الذ بالفــرار فتــم التعميــم عنــه و القبــض عليــه‪،‬‬\n      ‫وصــدر التقريــر الكيميائــي بإيجابيــة العينــة املرســلة‪ ،‬أقــرار املدعــى‬\n\n‫‪101‬‬\n\f‫عليــه باحليــازة ألجــل االســتخدام‪ ،‬ثبــوت إدانــة املدعــى عليــه باحليــازة‬\n‫ألجــل االســتخدام‪ ،‬تعزيــر املدعــى عليــه بالســجن واملنــع مــن الســفر‪،‬‬\n                               ‫تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬املــازم القضائــي يف احملكمــة‬\n‫اجلزائيــة باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                                            ‫ّ‬\n‫احملكمــة اجلزائيــة يف محافظــة االحســاء املكلــف برقــم ‪34167081‬‬\n‫وتاريــخ ‪1434/04/13‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34891311‬وتاريــخ‬\n‫‪1434/04/13‬ه ـ وبنــاء علــى تعميــدي مــن فضيلــة القاضــي ‪.........‬‬\n‫باخلطــاب رقــم ‪ 331633101‬يف ‪1433/8/17‬ه ـ ففــي يــوم اإلثنــن‬\n‫املوافــق‪ 1434/04/22‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 00‬وفيهــا‬\n‫حضــر املدعــي العــام ‪ .........‬وحضــر حلضــوره املدعــى عليــه‪ .........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .........‬وفيهــا ادعــى املدعــي‬\n‫قائــا يف دعــواه أنــه باالطــاع علــى محضــر القبــض رقــم (‪).........‬‬\n‫وتاريــخ ‪1434/2/13‬ه ـ ا ُملعــد مــن قبــل دوريــات األمــن باالحســاء تبــن‬\n‫أنــه مت االشــتباه بســيارة نــوع (‪ )........‬صنــع ‪2001‬م حتمــل اللوحــة رقــم‬\n‫(‪ ).........‬لونهــا فضــي بقيــادة املتهــم لســيره باجتــاه عكــس الطريــق‬\n‫وبعــد اســتيقافه رمــى كيــس بداخلــه عــدد (‪ )14‬حبــة يشــتبه أن تكــون‬\n‫محظــورة ثــم الذ بالفــرار ومت التعميــم عليــه والقبــض عليــه بتاريــخ‬\n‫‪1434/2/15‬هــ‪ .‬وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪).........‬‬\n‫لعــام ‪1434‬ه ـ إيجابيــة عينــة مــا مت ضبطــه ملــادة اإلمفيتامــن و املــدرج يف‬\n‫اجلــدول (‪ )2‬فئــة (ب) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n                                                                                     ‫‪102‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":101,"source_page_end":102,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dd1cd56f5c66b628df8e55b0fe7e58fac724d7a42e9069a038dbe9fc3be87040","normalized_text_hash":"817f2b093ec19eb0407d0db97f178c03d9a5cd31a1cb4f0e620a86052d3f30b1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p101-34198256"},{"id":"7eaf3f65-437d-5479-a950-3ce137c58b41","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها وتستر على مصدرها -محاولة إدخال مخدر إلى السجن -إقرار -إدانة - التعزير بالسجن واجللد واملنع من السفر ..","document_number":"34193641","case_number":"34167643","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/21","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها وتستر على مصدرها -محاولة إدخال مخدر إلى السجن -إقرار -إدانة - التعزير بالسجن واجللد واملنع من السفر ..","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34193641:‬تاريخه ‪1434/04/21:‬هـ‬\n                  ‫رقم الدعوى ‪34167643:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 341095246‬تاريخه‪1434/06/13:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيهــا وتســتر‬\n‫علــى مصدرهــا‪ -‬محاولــة إدخــال مخــدر إلــى الســجن‪ -‬إقــرار‪ -‬إدانــة ‪-‬‬\n                         ‫التعزيــر بالســجن واجللــد واملنــع مــن الســفر ‪..‬‬\n\n\n\n\n   ‫‪ -1‬املواد (‪ )41‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n                          ‫‪ -2‬املادة (‪ )29‬من نظام السجن والتوقيف‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيازتــه احلبــوب احملظــورة‬\n‫احملتويــة علــى اإلمفيتامــن والكلونازيبــام بقصــد التعاطــي وتعاطيــه‬\n‫لهــا ومحاولتــه إدخالهــا للتوقيــف وتســتره علــى مصــدر املخــدر‪،‬‬\n‫واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحة‬\n‫املخــدرات واملؤثــرات العقليــة وبعقوبــة الســجن الــواردة يف نظــام الســجن‬\n‫والتوقيــف‪ ،‬حيــث إنــه مت تفتيــش الســيارة التــي يقودهــا فعثــر فيهــا علــى‬\n‫حبــوب الكلونازيبــام احملظــورة وأثنــاء تفتيشــه شــخصي ًا قبــل إدخالــه‬\n‫إلــى التوقيــف عثــر يف مالبســه الداخليــة علــى حبــوب اإلمفيتامــن‬\n‫احملظــورة‪ ،‬وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة‬\n‫املرســلة لإلمفيتامــن والكلونازيبــام احملظوريــن‪ ،‬أقــر أمــام احملكمــة‬\n\n                                                                                   ‫‪106‬‬\n\f      ‫مبــا أســنده إليــه املدعــي العــام‪ ،‬فقضــت احملكمــة بإدانــة املدعــى عليــه‬\n      ‫بجميــع مــا نســب إليــه وقــررت جلــده ســبعني جلــدة لتعاطــي احلبــوب‬\n      ‫احملظــورة وســجنه ملــدة ســتة شــهر ومنعــه مــن الســفر خــارج اململكــة‬\n      ‫ملــدة ســنتني حليــازة احلبــوب احملظــورة بقصــد التعاطــي وســجنه ملــدة ســتة‬\n      ‫شــهر حملاولتــه إدخالهــا للتوقيــف وتســتره علــى مصــدر املخــدر‪ -‬قنــع‬\n      ‫املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬وقــررت محكمــة‬\n                                            ‫االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 34167643‬وتاريــخ ‪ 1434/04/13‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34894077‬وتاريــخ ‪ 1434/04/13‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافــق‪ 1434/04/20‬ه ـ افتتحــت اجللســة الســاعة ‪09 :15‬‬\n      ‫وفيهــا قــدم املدعــي العــام ‪ /‬الئحــة دعــوى عامــة ضــد ‪ /‬املدعــى عليــه‬\n      ‫‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬حيــث‬\n      ‫إنــه بتاريــخ ‪1434/2/23‬ه ـ قبــض علــى املذكــور مــن قبــل إحــدى‬\n      ‫فــرق دوريــات األمــن أثنــاء قيــام الفرقــة بعملهــا بحــي ‪........‬حيــث‬\n      ‫اشــتبهت الفرقــة بســيارة مــن نــوع (‪ )....‬تســير بــدون لوحــات بقيــادة‬\n      ‫املذكــور ‪ ،‬وباســتيقافه وتفتيــش الســيارة وجــد علــى املرتبــة اخللفيــة‬\n      ‫شــنطة يدويــة بداخلهــا(‪ )14‬أربعــة عشــر حبــة يشــتبه ان تكــون مــن‬\n      ‫حبــوب ( الــروش ) احملظــورة ووجــد لوحــات عائــدة لســيارات وجهــاز‬\n      ‫تابــع لشــركة ‪( .................‬جــرى معاجلــة ذلــك مــن قبــل شــرطة ‪........‬‬\n\n‫‪107‬‬\n\f‫مبوجــب خطابهــم رقــم (‪ )........‬وتاريخ‪1434/2/24‬ه ـ ) واثنــاء تفتيشــه‬\n‫قبــل ادخالــه توقيــف مكافحــة املخــدرات بشــرق الريــاض عثــر بداخــل‬\n‫مالبســه الداخليــة (‪ )17‬ســبع عشــرة حبــة وأربعــه أنصــاف حتمــل عالمــة‬\n‫الكبتاجــون احملظــور جــرى مخاطبــة مكافحــة املخــدرات بشــرق‬\n‫الريــاض باخلطــاب رقــم (‪ )........‬وتاريــخ ‪1434/4/3‬ه ـ إلحالــة مــا يتعلــق‬\n‫بقيــادة املذكــور لســيارة بــدون لوحــات للجهــة املختصــة‪ .‬وقــد أثبــت‬\n‫التقريــران الكيميائيــان الشــرعيان الصــادران مــن مركــز مراقبــة‬\n‫الســموم والكيميــاء الطبيــة الشــرعية بالريــاض املرفقــان رقــم (‪)........‬‬\n‫ورقــم (‪ )........‬لعــام ‪1434‬ه ـ احتــواء احلبــوب التــي حتمــل عالمــة الــروش‬\n‫لعقــار ( كلونازيبــام) وهــو مــن املــواد املهدئــة املدرجــة باجلــدول رقــم (‪)2‬‬\n‫فئــة (د) مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة‪ .‬واحتــواء‬\n‫عينــة احلبــوب املضبوطــة يف مالبســه الداخليــة لإلمفيتامــن وهــو مــن‬\n‫املــواد املنبهــة واملدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وبســماع أقــوال األول األوليــة‬\n‫اقــر بعائديــة حبــوب الكبتاجــون املضبوطــة لــه بقصــد التعاطــي وافــاد‬\n‫ان حبــوب الــروش املضبوطــة تعــود ألخيــه وباســتجوابه أقــر بعائديــة‬\n‫جميــع مــا ضبــط لــه احلبــوب بقصــد التعاطــي وتعاطيــه إياهــا وأفــاد‬\n‫أنــه حصــل عليهــا مــن شــخص مينــي اجلنســية وانــه ال عالقــة ألخيــه مبــا‬\n‫ضبــط معــه حيــث انــه مــن اخلــوف واالرتبــاك ذكــر اســم اخيــه اثنــاء‬\n‫ســماع اقوالــه مبكافحــة املخــدرات‪ .‬وقــد اســفرت اجــراءات التحقيــق‬\n‫عــن توجيــه االتهــام الــى ‪/‬املدعــى عليــه بحيــازة (‪ )14‬اربعــة عشــر حبــة‬\n‫حتــوي عقــار الكلونازيبــام املهــدئ احملظــور و(‪ )17‬ســبعة عشــرة حبــة‬\n‫وأربعــة انصــاف احلبــة مــن حبــوب اإلمفيتامــن املنبــه احملظــور بقصــد‬\n\n\n                                                                                      ‫‪108‬‬\n\f      ‫التعاطــي وتعاطيــه احلبــوب احملظــورة املجــرم مبوجــب املــادة (الثالثــة)‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ومحاولتــه ادخــال حبــوب‬\n      ‫محظــورة لتوقيــف مكافحــة املخــدرات بشــرق الريــاض املعاقــب علــى‬\n      ‫ذلــك مبوجــب املــادة (‪ )29‬مــن نظــام الســجن والتوقيف الصادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )31/‬وتاريــخ ‪1398/6/21‬ه ـ وتســتره عــن مصــدر مــا‬\n      ‫ضبــط املعاقــب علــى ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬مــا‬\n      ‫تضمنــه اعترافــه مبحضــر اســتجوابه املنــوه عنــه واملــدون علــى اللفــات‬\n      ‫رقــم (‪ 18‬ـ‪ -2 ) 20‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة‬\n      ‫املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ ) 2‬مــن ملــف ضبــط اجــراءات‬\n      ‫قضيــة مخــدرات لفــه رقــم(‪ -3 )7‬مــا تضمنــه محضــر القبــض مــن وقائــع‬\n      ‫املنــوه عنــه واملرفــق لفــة رقــم (‪ -4 .) 1،2‬مــا تضمنــه محضــر التفتيــش‬\n      ‫املعــد مــن مكافحــة املخــدرات املنــوه عنــه واملرفــق لفــة رقــم (‪-5 .)10‬‬\n      ‫مــا تضمنــه التقريــران الكيميائيــان الشــرعيان املنــوه عنهمــا املرفقــان‬\n      ‫علــى اللفتــن رقــم (‪ .)26،27‬وحيــث إن مــا أقــدم عليــه املذكــور فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا اطلــب اثبــات ادانتــه مبــا أســند‬\n      ‫إليــه واحلكــم باآلتــي‪1 :‬ـ بالعقوبــة الــواردة يف الفقــرة (األولــى) مــن املــادة‬\n      ‫(‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واملــادة (‪)30‬‬\n      ‫مــن الالئحــة التنفيذيــة للنظــام املشــار إليــه لقــاء مــا أســند إليــه‪2 .‬ـ منعــه‬\n      ‫مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة ســجنه وفق ـ ًا‬\n      ‫للفقــرة (األولــى) مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه‪3 .‬ـ عقوبــة‬\n      ‫تعزيريــة بحقــه لقــاء تســتره علــى مصــدر مــا ضبــط‪4 .‬ـ بالعقوبــة الــواردة‬\n      ‫يف املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف بحدهــا األعلــى بحقــه‬\n\n\n‫‪109‬‬\n\f‫خلطــورة مــا أقــدم عليــه ولتماديــه يف غيــه اســتناد ًا لبرقيــة صاحــب الســمو‬\n‫امللكــي اميــر منطقــة الريــاض بالنيابــة رقــم (‪/16745‬س) وتاريــخ‬\n‫‪1430/8/17‬هــ‪ .‬وبــاهلل التوفيــق وبســؤال املدعــى عليــه عــن دعــوى‬\n‫ا مــا ذكــره املدعــي العــام يف‬  ‫املدعــي العــام اجــاب املدعــى عليــه قائ ـ ً‬\n‫ا فقــد حــزت (‪ )14‬اربعــة عشــر حبــة‬    ‫دعــواه كلــه صحيــح جملــة وتفصيـ ً‬\n‫حتــوي عقــار الكلونازيبــام املهــدئ احملظــور و(‪ )17‬ســبعة عشــرة حبــة‬\n‫وأربعــة انصــاف احلبــة مــن حبــوب اإلمفيتامــن املنبــه احملظــور بقصــد‬\n‫التعاطــي وتعاطيــت احلبــوب احملظــورة وحاولــت ادخــال حبــوب محظــورة‬\n‫بتوقيــف مكافحــة املخــدرات بشــرق الريــاض وتســترت علــى مصــدر مــا‬\n‫ضبــط وليــس علــي ســوابق هكــذا اجــاب وباالطــاع علــى اوراق املعاملــة‬\n‫وجــدت تقريــر كيميائــي شــرعي رقــم (‪ )........‬لعــام ‪1434‬ه ـ واملتضمــن‬\n‫إيجابيــة العينــة املرســلة ملــادة كلونازيبــام وهــو مــن املــواد املهدئــة‬\n‫كمــا جــرى االطــاع علــى تقريــر كيميائــي شــرعي رقــم (‪ )........‬لعــام‬\n‫‪1434‬ه ـ واملتضمــن ايجابيــة العينــة املرســلة ملــادة اإلمفيتامــن وهــو مــن‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واالجابــة وحيــث اقــر‬   ‫املــواد املنبهــة فبنـ ً‬\n‫املدعــى عليــه بصحــة دعــوى املدعــي العــام وحيــث ان مــا أقــدم عليــه‬\n‫ـاء علــى املــادة ‪ 41‬و ‪ 56‬مــن نظــام‬‫فعــل محــرم يســتحق عليــه اجلــزاء وبنـ ً‬\n‫ـاء علــى املــادة ‪ 29‬مــن نظــام الســجن والتوقيــف‬  ‫مكافحــة املخــدرات وبنـ ً‬\n‫لهــذا كلــه فقــد ثبــت لــدي ادانــة املدعــى عليــه بحيــازة (‪ )14‬اربعــة عشــر‬\n‫حبــة حتــوي عقــار الكلونازيبــام املهــدئ احملظــور و(‪ )17‬ســبع عشــرة‬\n‫حبــة وأربعــة انصــاف احلبــة مــن حبــوب اإلمفيتامــن املنبــه احملظــور‬\n‫بقصــد التعاطــي وتعاطيــه احلبــوب احملظــورة ومحاولتــه إدخــال حبــوب‬\n‫محظــورة بتوقيــف مكافحــة املخــدرات بشــرق الريــاض وتســتره علــى‬\n\n\n                                                                                          ‫‪110‬‬\n\f      ‫مصــدر مــا ضبــط وقــررت تعزيــره لقــاء حيــازة احلبــوب احملظــورة بقصــد‬\n      ‫التعاطــي املذكــورة بســجنه ملــدة ســتة اشــهر وتعزيــره لقــاء محاولتــه‬\n      ‫ادخــال احلبــوب احملظــورة بســجنه ملــدة ســتة أشــهر ليصبــح مجمــوع‬\n      ‫ســجنه لقــاء حيــازة احلبــوب احملظــورة بقصــد التعاطــي ومحاولــة ادخــال‬\n      ‫احلبــوب احملظــورة مــدة ســنة مــع احتســاب مــدة ايقافــه الســابقة يف هــذه‬\n      ‫القضيــة وجلــده لقــاء تعاطيــه احلبــوب احملظــورة ســبعني جلــده ومنعــه مــن‬\n      ‫الســفر الــى خــارج اململكــة ملــدة ســنتني تبــدا بعــد نهايــة تنفيــذ عقوبــة‬\n      ‫ســجنه املذكــورة وأمــا مــا يتعلــق بتعزيــره لقــاء التســتر فهــو داخــل يف‬\n      ‫العقوبــة التعزيريــة املذكــورة ومبــا ذكــر حكمــت وبعــرض احلكــم‬\n      ‫علــى املدعــي العــام واملدعــى عليــه قــرر املدعــى عليــه القناعــة باحلكــم‬\n      ‫وامــا املدعــي العــام فقــرر عــدم القناعــة باحلكــم وطلــب التمييــز فأجبتــه‬\n      ‫ا إننــي أكتفــي بالئحــة الدعــوى‬      ‫لطلبــه ثــم قــرر املدعــي العــام قائ ـ ً‬\n      ‫العامــة فهــي الالئحــة االعتراضيــة هكــذا قــرر ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/04/20‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ،،‬ففقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزئيــة بالريــاض برقــم‬\n      ‫‪ 34894077‬وتاريــخ ‪1434/05/01‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ....../‬املســجل برقــم ‪34193641‬‬\n      ‫وتاريــخ ‪1434/04/21‬ه ـ اخلــاص بدعــوى املدعــي العــام ضد‪/‬املدعــى‬\n      ‫عليــه التهامــه بقضيــة مخــدرات علــى النحــو املوضح بالقرار املتضمن‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه ‪ .‬وبدراســة القــرار وصــورة‬\n      ‫ضبطــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق‬\n             ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n‫‪111‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":106,"source_page_end":111,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"482b5b475efc892a0f297a4c0a711be53a797e8c4b45b422491ee7b1db42bc54","normalized_text_hash":"70ab14d9db7820f66e71baacd7026156b084acb609361189b2c81cc249fa77d8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p106-34193641"},{"id":"cb457d18-29ad-5231-93eb-0b2a685d4819","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلشيش املخدر بقصد التعاطي -إقرار -التعزير بالسجن -منع من السفر.","document_number":"34274417","case_number":"34171923","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية السادسة برقم 34283832يف 1434/7/30ه جاء","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/18","year":"1434","subject":"مخدرات -حيازة احلشيش املخدر بقصد التعاطي -إقرار -التعزير بالسجن -منع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34274417 :‬تاريخه‪1434/7/18 :‬هـ‬\n                   ‫رقم الدعوى‪34171923 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34306345‬تاريخه‪1434/08/25 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة احلشــيش املخــدر بقصــد التعاطــي ‪ -‬إقــرار ‪ -‬التعزير‬\n                                              ‫بالســجن ‪ -‬منــع من الســفر‪.‬‬\n\n\n\n\n                 ‫املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد املدعــى عليــه بحيــازة احلشــيش املخــدر بقصــد‬\n‫التعاطــي‪ ،‬طلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه‬\n‫بالســجن بحــده األعلــى لتعــدد ســوابقه وفق ـ ًا للفقــرة األولــى مــن املــادة‬\n‫(‪)56‬مــن نظــام مكافحــة املخــدرات واملؤاثــرات العقليــة‪ ،‬مت القبــض‬\n‫علــى املدعــى عليــه بعــد ضبطــه مــن إحــدى الدوريــات حيــث مت االشــتباه‬\n‫بــه وبتفتيشــه عثــر معــه بجيبــه علــى قطعــة مــن احلشــيش املخــدر‪ ،‬إقــرار‬\n‫املدعــى عليــه بالدعــوى‪ ،‬تعزيــر املدعــى عليــه بالســجن واملنــع مــن‬\n                   ‫الســفر‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                     ‫‪112‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالطائــف برقــم ‪ 34171923‬وتاريــخ ‪1434/04/15‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34917432‬وتاريــخ ‪ 1434/04/15‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق ‪1434/07/18‬ه ـ افتتحــت اجللســة الســاعة ‪30‬‬\n      ‫‪ 09 :‬وفيهــا حضــر املدعــي العــام ‪ ...........‬بالتعميــد رقــم ‪ 1607‬يف‬\n      ‫‪1433/10/18‬ه ـ وادعــى علــى احلاضــر باملجلــس الشــرعي ‪...........‬‬\n      ‫ا أنــه بتاريــخ‬\n                     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ............‬قائـ ً‬\n      ‫‪1434/3/17‬ه ـ ضبطــت دوريــة مكافحــة املخــدرات بطريــق الريــاض‬\n      ‫الســيارة نــوع ‪ ......‬رقــم لوحتهــا (‪ )...........‬قيــادة ‪ - ........... :‬لــم يتهــم‬\n      ‫لعــدم األدلــة ‪ -‬ويرافقــه املدعــى عليــه وبتفتيــش املدعــى عليــه عثــر بجيــب‬\n      ‫ثوبــه علــى قطعــة تــزن (‪ )0،2‬عشــري جــرام ثبــت بالتقريــر الكيميائــي‬\n      ‫الشــرعي رقــم (‪ )...........‬يف ‪1434/3/23‬ه ـ ايجابيتهــا للحشــيش املخــدر‬\n      ‫املــدرج باجلــدول (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات وباســتجواب‬\n      ‫املدعــى عليــه أقــر بأنــه قبــض عليــه وبتفتيشــه عثــر بجيــب ثوبــه علــى‬\n      ‫قطعــة تــزن (‪ )0.2‬عشــري جــرام مــن احلشــيش وهــي لــه بقصــد التعاطــي‬\n      ‫وقــد أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بحيــازة قطعــة‬\n      ‫تــزن (‪ )0.2‬عشــري جــرام مــن احلشــيش املخــدر بقصــد التعاطــي واملجــرم‬\n      ‫نظام ـ ًا وفق ـ ًا للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬يف ‪1426/7/8‬ه ـ‬\n      ‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬إقــراره املنــوه عنــه املــدون لفــة (‪)1‬‬\n\n‫‪113‬‬\n\f‫صفحــة (‪ -2 . )11‬محضــر القبــض والتفتيــش املنــوه عنــه املــدون لفــة (‪)1‬‬\n‫صفحــة (‪ -3 . )11‬التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة‬\n‫(‪ . )14‬وبالبحــث عــن ســوابقه عثــر عليــه ثــاث ســوابق مســجلة ‪ :‬قتــل‬\n‫ومضاربــة وشــرب املســكرات وحيــث إن مــا أقــدم عليــه املدعــى عليــه‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم شــرع ًا ومجــرم نظامـ ًا‬\n‫وفق ـ ًا ملــا أشــير إليــه لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n‫باآلتــي‪ -1 :‬الســجن بحــده األعلــى وفقـ ًا للفقــرة األولى مــن املادة الواحدة‬\n‫واألربعــن ووفق ـ ًا للتعميــم رقــم (‪ )593958/5/1‬يف ‪1429/8/23‬ه ـ‬\n‫لتعــدد ســوابقه وعــدم إرتداعــه ‪ -2 .‬منعــه مــن الســفر خــارج اململكــة‬\n‫بعــد تنفيــذ العقوبــة وفقـ ًا للفقــرة األولــى مــن املــادة السادســة واخلمســن‬\n‫هــذه دعــواي ‪ .‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب ما‬\n‫ذكــره املدعــي العــام صحيــح والســوابق التــي علــي صحيحــة وباالطــاع‬\n‫علــى التقريــر الكيميائــي الشــرعي رقــم ‪ ...........‬يف ‪1434/3/23‬ه ـ‬\n‫اثبــت احتــواء العينــة علــى مــادة احلشــيش املخــدر فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة املتضمنــة املصادقــة علــى الدعــوى ولوجــود ثــاث‬\n‫ســوابق مصــادق عليهــا إحداهــا قتــل وايجابيــة التقريــر الكيميائــي‬\n‫فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة قطعــة مــن احلشــيش تــزن‬\n‫‪ 0.2‬جــم وحكمــت عليــه بســجنه ملــدة ســنة وســتة أشــهر ومنعــه مــن‬\n‫الســفر خــارج اململكــة ملــدة ســنتني تبــدأ بعــد انتهــاء العقوبــة بنــاء علــى‬\n‫املــادة ‪ 41‬واملــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات وبعــرض احلكــم‬\n‫علــى املدعــى عليــه اعتــرض علــى احلكــم بــدون الئحــة واعتــرض املدعــي‬\n‫العــام بالئحــة اعتراضيــة فجــرى تســليمه نســخة احلكــم وأفهمتــه بــأن‬\n‫مــدة تقــدمي الالئحــة ثالثــن يومـ ًا بنــاء علــى املــادة ‪ 194‬و ‪ 195‬مــن نظــام‬\n\n\n                                                                                       ‫‪114‬‬\n\f      ‫االجــراءات اجلزائيــة وبــاهلل التوفيــق حــرر يف ‪1434/7/18‬ه ـ الســاعة‬\n                                                                    ‫العاشــرة صباح ـ ًا ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالطائــف برقــم ‪ 34171923‬وتاريــخ ‪ 1434/04/15‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34917432‬وتاريــخ ‪ 1434/04/15‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافــق ‪1434/08/13‬ه ـ افتتحــت اجللســة الســاعة الواحــدة‬\n      ‫حيــث عــادت املعاملــة مــن محكمــة اإلســتئناف مالحــظ عليهــا بقــرار‬\n      ‫الدائــرة اجلزائيــة السادســة برقــم ‪ 34283832‬يف ‪1434/7/30‬ه ـ جــاء‬\n      ‫فيــه وبدراســة القــرار وصــورة ضبطــه والئحتــه اإلعتراضيــة تقــرر‬\n      ‫إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن فضيلتــه أثبــت حيــازة املدعــى‬\n      ‫عليــه للحشــيش املخــدر ولــم يذكــر القصــد وجوابــا علــى ماذكــره‬\n      ‫أصحــاب الفضيلــة فقــد كان ذلــك ســقطا مــن الكاتــب وصوابــه‬\n      ‫أن احليــازة بقصــد التعاطــي كمــا هــو مذكــور يف الدعــوى واإلجابــة‬\n      ‫واحلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/13‬ه ـ الســاعة الواحــدة والربــع ‪.‬‬\n      ‫احلمد هلل وحده وبعد ففي يوم األحد املوافق‪ 1434/09/13‬هـ افتتحت‬\n      ‫اجللســة الســاعة الثانيــة حيــث عــادت املعاملــة مــن محكمــة اإلســتئناف‬\n      ‫مصادقــا عليهــا بقــرار الدائــرة اجلزائيــة السادســة برقــم ‪ 34306345‬يف‬\n      ‫‪1434/8/25‬ه ـ ولــذا جــرى إثباتــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1434/09/13‬ه ـ‬\n                                                              ‫الســاعة الثانيــة والربــع‪.‬‬\n                 ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n\n\n‫‪115‬‬\n\f‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n‫مبكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه‬\n‫احملكمــة بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بالطائــف‬\n‫رقــم (‪ )341579985‬وتاريــخ (‪1434/8/15‬هــ) املرفــق بهــا القــرار‬\n‫رقــم (‪ )34272417‬وتاريــخ (‪1434/7/18‬هــ) الصــادر مــن فضيلــة‬\n‫الشــيخ‪ .........../‬القاضــي باحملكمــة اجلزائيــة بالطائف‪،‬املتضمــن‬\n‫دعــوى املدعــي العــام ضــد‪ .........../‬ســعودي اجلنســية ‪ ،‬املتهــم يف‬\n‫حشــيش مخــدر‪ ،‬احملكــوم فيــه مبــادون باطنــه ‪ ،‬واملالحــظ عليــه‬\n‫بقــرار محكمة االســتئناف رقم‪34283832‬وتاريخ‪1434/7/30‬هـ‪،‬وب‬\n‫دراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم بعــد اجلــواب األخيــر‪ ،‬واهلل املوفق‪،‬وصلــى اهلل علــى نبينــا‬\n                                        ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                ‫‪116‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":112,"source_page_end":116,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"214ea13fd897ff9b095c7ee2ca76f5497815ad98504df4649904588d57a40400","normalized_text_hash":"fe4dcd9438d7c47a4915208bf213268ae0a7ea658fc489f2e7455d51fdd42e44","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p112-34274417"},{"id":"6a443d27-97f8-5b60-8153-9cf1dbc0dcf5","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة كوكاين بقصد الترويج والشروع يف بيعه بقصد االجتار -إقرار -إدانة -املتهم وافد -نزول عن احلد األدنى للعقوبة -تعزير بالسجن واجللد والغرامة واالبعاد من الباد .","document_number":"34268577","case_number":"34172801","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/15","year":"1434","subject":"مخدرات -حيازة كوكاين بقصد الترويج والشروع يف بيعه بقصد االجتار -إقرار -إدانة -املتهم وافد -نزول عن احلد األدنى للعقوبة -تعزير بالسجن واجللد والغرامة واالبعاد من الباد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34268577:‬تاريخه‪1434/07/15 :‬هـ‬\n                          ‫رقم الدعوى‪34172801:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34354992‬تاريخه‪1434/11/09:‬هـ‬\n\n\n       ‫مخــدرات‪ -‬حيــازة كوكايــن بقصــد الترويــج والشــروع يف بيعــه بقصد‬\n       ‫االجتــار‪ -‬إقــرار‪ -‬إدانــة‪ -‬املتهــم وافــد ‪-‬نــزول عــن احلــد األدنــى للعقوبــة‬\n                     ‫‪ -‬تعزيــر بالســجن واجللــد والغرامــة واالبعــاد مــن البــاد ‪.‬‬\n\n\n\n\n       ‫املــواد (‪ )38‬و(‪ )53‬و(‪ )56‬و (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                       ‫العقلية‪.‬‬\n\n\n\n       ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n       ‫بحيــازة الكوكايــن املخــدر بقصــد الترويــج وشــروعه يف بيعــه بقصــد‬\n       ‫االجتــار‪ ،‬واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة واإلبعــاد عــن‬\n       ‫البــاد طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ -‬مت االتفاق‬\n       ‫معه على شراء كمية من مادة الكراك املخدر وبعد مقابلته للمصدر‬\n       ‫ا مــن يــده اليســرى تبــن أن بــه مــادة‬\n                                                ‫تقدمــت الفرقــة نحــوه فرمــى منديـ ً‬\n       ‫بيضــاء اللــون هــي الكميــة املتفــق عليهــا‪ -‬أثبــت التقريــر الكيميائــي‬\n       ‫الشــرعي إيجابيــة العينــة املرســلة للكوكايــن املخــدر‪ -‬أنكــر أمــام‬\n       ‫احملكمــة مــا أســنده إليــه املدعــي العــام ثــم أقــر بذلــك بعــد مواجهتــه‬\n       ‫بشــهود محضــر القبــض‪ -‬قضــت احملكمــة بإدانــة املدعــى عليــه بجميــع‬\n\n‫‪117‬‬\n\f‫مــا نســب إليــه وقــررت ســجنه ملــدة ســنتني ونصــف الســنة وجلــده مائتــي‬\n‫جلــدة علــى أربــع دفعــات وتغرميــه مبلــغ ألفــي ريــال وإبعــاده عــن البــاد‬\n‫بعــد انتهــاء محكوميتــه‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي‬\n       ‫العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وبعــد فــدي أنــا‬\n‫‪ ........‬القاضــي باحملكمــة اجلزائيــة مبحافظــة جــدة والقائــم بعمــل‬\n‫القاضــي باحملكمــة فضيلــة الشــيخ ‪ ........‬مبوجــب خطــاب التكليــف‬\n‫الصــادر مــن فضيلــة مســاعد رئيــس احملكمــة برقــم ‪34965789‬وتاريــخ‬\n‫‪1434/04/20‬ه ـ افتتحــت اجللســة يف متــام الســاعة العاشــرة صباحـ ًا مــن‬\n‫ـاء علــى املعاملــة احملالــة‬\n                            ‫هــذا اليــوم الثالثــاء املوافــق ‪1434/04/23‬ه ـ بنـ ً‬\n‫إلينــا بشــرح فضيلــة الرئيــس برقم ‪ 34172801‬وتاريــخ ‪1434/04/15‬هـ‬\n‫واملقيــدة برقــم ‪ 34911643‬وتاريــخ ‪1434/04/14‬ه ـ وفيهــا حضــر‬\n‫املدعــي العــام ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n‫عضــو هيئــة التحقيــق واالدعــاء العــام مبحافظــة جــدة املعمــد مــن هيئــة‬\n‫التحقيــق واالدعــاء العــام مبوجــب خطــاب التعميــد رقم (ه ـ م‪)3200/6/‬‬\n‫وتاريــخ ‪1434/01/13‬ه ـ وقــدم الئحــة دعــواه ضد احلاضــر معه باملجلس‬\n‫الشــرعي ‪ )33( ،........‬عامـ ًا ‪ ،‬تشــادي اجلنســية مبوجــب البطاقــة البديلة‬\n‫رقــم‪ ، ........‬الصــادرة مــن مكافحــة املخــدرات مبحافظــة جــدة بتاريــخ‬\n‫‪1434/1/29‬ه ـ ‪ ،‬موقــوف بالســجن العــام مبحافظــة ج ـ ــدة مبوجــب‬\n‫أمــر متديــد التوقيــف رق ــم(هـ م‪ )7862/5/2‬وتاريـ ــخ ‪1434/2/3‬ه ـ‬\n‫اســتنادا للقــرار الــوزاري رقــم (‪ )1900‬املبنــي علــى املــادة (‪ )112‬مــن‬\n\n                                                                                      ‫‪118‬‬\n\f      ‫نظــام اإلجــراءات اجلزائيــة ‪ ،‬املقبــوض عليــه بتاريــخ ‪1434/1/29‬ه ـ‬\n      ‫فإنــه بتاريــخ ‪1434/1/29‬ه ـ قبــض عليــه مــن قبــل فرقــة مكافحــة‬\n      ‫املخــدرات بجــدة إثــر االتفــاق معــه علــى شــراء كميــة مــن مــادة الكراك‬\n      ‫املخــدر مببلــغ (‪ )2800‬ألفــن وثمامنائــة ريــال ‪ ،‬وحضــوره ومعــه شــخص‬\n      ‫ا مــن يــده‬\n                 ‫ومقابلتهمــا للمصــدر ‪ ،‬وعنــد تقــدم الفرقــة نحــوه رمــى منديـ ً‬\n      ‫اليســرى تبــن أن بــه مــادة بيضــاء اللــون تــزن (‪ )4‬أربعــة جرامــات وهــي‬\n      ‫الكميــة املتفــق عليهــا ‪ ،‬ومتكــن الشــخص اآلخــر مــن الهــرب وقــد أثبــت‬\n      ‫التقريــر الكيمي ـ ـ ــائي الشــرعي رق ـ ـ ــم (‪/379‬ك ش م) لعـ ـ ــام ‪1434‬ه ـ‬\n      ‫احتــواء عين ــة مــا مت ضبطــه علــى مــادة الكوكايــن املخــدر املدرجــة‬\n      ‫باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة وانتهــى التحقيــق إلــى اتهــام املدعــى عليــه بحيــازة (‪ )4‬أربــع‬\n      ‫جرامــات مــن مــادة الكوكايــن املخــدر بقصــد الترويــج والشــروع يف‬\n      ‫بيعهــا بقصــد االجتــار‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪ -1 -:‬مــا ورد يف‬\n      ‫ا املرفــق لفة‬‫شــهادة الشــهود الــواردة مبحضــر الضبــط املنــوه عنــه تفصيـ ً‬\n      ‫رقــم (‪ -2 .)1‬مــا ورد بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق‬\n      ‫لفــة رقــم (‪ )23‬وباالطــاع علــى صحيفــة احلالــة اجلنائيــة عثــر لــه علــى‬\n      ‫ســابقتي ترويــج املخــدرات وحيــث أن مــا أقــدم عليــه املدعــى عليــه وهــو‬\n      ‫بكامــل أهليتــه املعتبــرة شــرع ًا مــن األفعــال احملرمــة شــرع ًا واملجرمــة‬\n      ‫نظام ـ ًا طبق ـ ًا للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة الصــادر باملرســوم امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬هــ‪،‬‬\n      ‫لــذا اطلب‪/‬إثبــات مــا أســند إليــه واحلكــم عليــه بالعقوبــات األصليــة‬\n      ‫والتكميليــة التاليــة‪ )1 :‬بالســجن واجللــد والغرامــة مــع تشــديد العقوبــة‬\n      ‫عليــه اســتناد ًا للفقــرة (‪ )1‬والفقــرة (‪ )2‬احلالــة (ج) مــن املــادة (‪ )38‬مــن‬\n\n\n‫‪119‬‬\n\f‫نظــام مكافحــة املخــدرات املشــار إليــه‪ )3 .‬إبعــاده خلــارج اململكــة بعــد‬\n‫االنتهــاء مــن تنفيــذ عقوبتــه وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن نظــام‬\n‫مكافحــة املخــدرات املشــار إليــه هكــذا ادعــى وبتــاوة دعــوى املدعــي‬\n‫ا مــا ذكــره املدعــي‬  ‫العــام علــى املدعــى عليــه أجــاب يحســن العربيــة قائـ ً‬\n‫العــام مــن اتهامــي بحيــازة (‪ )4‬أربــع جرامــات مــن مــادة الكوكايــن‬\n‫املخــدر بقصــد الترويــج والشــروع يف بيعهــا بقصــد االجتــار فهــذا كلــه‬\n‫ا والصحيــح ليــس لــي عالقــة مبــا ضبــط‬        ‫غيــر صحيــح جملــة وتفصي ـ ً‬\n‫بجانبــي وال أقــوم بترويــج املخــدرات وبســؤال املدعــي العــام عــن البينــة‬\n‫ـدي بينــة وأطلــب اإلمهــال إلحضارهــا يف اجللســة‬      ‫أجــاب بقولــه نعــم لـ ّ‬\n‫القادمــة فأجبتــه لطلبــه احلمــد هلل وحــده والصــاة والســام علــى مــن‬\n‫ال نبــي بعــده وبعــد فلــدي أنــا القاضــي باحملكمــة اجلزائيــة مبحافظــة‬\n‫جــدة افتتحــت اجللســة وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى‬\n‫عليــه وبســؤال املدعــي العــام عمــا رفعــت اجللســة الســابقة ألجلــه أحضــر‬\n‫كل مــن‪ /1 :‬جنــدي أول ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ /2 ........‬اجلنــدي ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ........‬ولــدى استشــهادهم شــهد كل واحــد منهــا بقولــه أشــهد هلل‬\n‫ـاء علــي إخباريــة مــن متعــاون مفادهــا مت االتفــاق مــع املدعــى‬\n                                                                   ‫تعالــى أنــه بنـ ً‬\n‫عليــه علــى شــراء كميــة مــن مــادة الكــراك املخــدر مببلــغ (‪)2800‬‬\n‫ألفــن وثمامنائــة ريــال ‪ ،‬وحضــوره ومعــه شــخص ومقابلتهمــا للمصــدر‬\n‫ا مــن يــده اليســرى تبــن أن‬      ‫‪ ،‬وعنــد تقــدم الفرقــة نحــوه رمــى مندي ـ ً‬\n‫بــه مــادة بيضــاء اللــون تــزن (‪ )4‬أربعــة جرامــات وهــي الكميــة املتفــق‬\n‫عليهــا ‪ ،‬ومتكــن الشــخص اآلخــر مــن الهــرب هــذا مــا لدينــا ونشــهد بــه‬\n‫أمــام اهلل ســبحانه وتعالــى ثــم رفعــت اجللســة بعــد ذلــك إلحضــار املدعــى‬\n\n\n                                                                                         ‫‪120‬‬\n\f      ‫عليــه وعــرض الشــهادة عليــه ويف جلســة أخــرى حضــر املدعــي العــام‬\n      ‫وأحضــر املدعــى عليــه وبعــرض شــهادة الشــهود علــى املدعــى عليــه‬\n      ‫ا وأنــا‬  ‫أجــاب جميــع مــا ورد بشــهادة الشــهود صحيــح جملــة وتفصي ـ ً‬\n      ‫ال‬‫نــادم علــى هــذا الفعــل وتائــب إلــى اهلل تعالــى ولــن أعــود ملثلــه مســتقب ً‬\n      ‫هــذا وقــد جــرى الرجــوع علــى أوراق املعاملــة ومنهــا التقريــر الكيميائــي‬\n      ‫الشــرعي املنــوه عنــه املرفــق لفــة رقــم (‪ )23‬املتضمــن احتــواء عين ــة مــا‬\n      ‫مت ضبطــه علــى مــادة الكوكايــن املخــدر املدرجــة باجلــدول رقــم (‪)1‬‬\n      ‫فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة كمــا‬\n      ‫جــرى االطــاع علــى مــا ورد يف شــهادة الشــهود الــواردة مبحضــر الضبــط‬\n      ‫ا املرفــق لفــة رقــم (‪ )1‬املتضمنــة مت القبــض عليــه مــن‬    ‫املنــوه عنــه تفصيـ ً‬\n      ‫قبــل فرقــة مكافحــة املخــدرات بجــدة إثــر االتفــاق معــه علــى شــراء‬\n      ‫كميــة مــن مــادة الكــراك املخــدر مببلــغ (‪ )2800‬ألفــن وثمامنائــة ريــال‬\n      ‫‪ ،‬وحضــوره ومعــه شــخص ومقابلتهمــا للمصــدر ‪ ،‬وعنــد تقــدم الفرقــة‬\n      ‫ا مــن يــده اليســرى تبــن أن بــه مــادة بيضــاء اللــون تــزن‬ ‫نحــوه رمــى منديـ ً‬\n      ‫(‪ )4‬أربعــة جرامــات وهــي الكميــة املتفــق عليهــا ‪ ،‬ومتكــن الشــخص‬\n      ‫اآلخــر مــن الهــرب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــر ًا‬\n      ‫إلــى أن املدعــى عليــه اعتــرف مبــا نســبه إليــه املدعــي العــام ونظــر ًا‬\n      ‫إلــى مــا جــاء يف أوراق املعاملــة وبعــد االطــاع علــى نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة وأن املدعــى عليــه األول ينطبــق بحقــه‬\n      ‫املــواد (‪ )56-53-38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫‪ ،‬وباالطــاع علــى صحيفــة ســوابق املدعــى عليــه عثــر لــه علــى ســابقتي‬\n      ‫ترويــج املخــدرات وبعــرض الســوابق عليــه أجــاب بقولــه صحيــح علـ ّـي‬\n      ‫هــذه الســوابق وقــد أخــذت جزاءهــا وأنــا تائــب منهــا فلمــا ســبق ولقلــة‬\n\n\n‫‪121‬‬\n\f‫الكميــة التــي قــام املدعــى عليــه بترويجهــا وكونــه أجنبــي وال فائــدة‬\n‫مــن طــول بقائــه يف الســجن وملقتضــى املــادة (‪ )60‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة التــي أجــازت النــزول عــن احلــد األدنــى يف‬\n‫العقوبــة املنصــوص عليــه يف املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات‬\n‫ـدي إدانــة املدعــى‬‫واملؤثــرات العقليــة فقــد قــررت مــا يلــي‪ /‬أوالً‪ :‬ثبــت لـ ّ‬\n‫بحيــازة (‪ )4‬أربــع جرامــات مــن مــادة الكوكايــن املخــدر بقصــد‬\n‫الترويــج والشــروع يف بيعهــا بقصــد االجتــار ثاني ـاً‪ :‬حكمــت بســجنه‬\n‫ملــدة ســنتني ونصــف الســنة يحتســب منهــا املــدة التــي قضاهــا يف الســجن‬\n‫بســبب هــذه القضيــة وجلــده مائتــي جلــدة مفرقــة علــى أربــع دفعــات كل‬\n‫دفعــة خمســن جلــدة بــن الدفعــة واألخــرى مــدة ال تقــل عــن عشــرة أيــام‬\n‫وتغرميــه مبلــغ وقــدره (‪ )2000‬ألفــن ريــال اســتناد ًا علــى املــواد (‪)60-38‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ثالث ـاً‪ :‬إبعــاده عــن‬\n‫البــاد بعــد انتهــاء محكوميتــه وعــدم الســماح لــه بدخولهــا إال فيمــا‬\n‫عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة اســتناد ًا علــى املــادة (‪)2/56‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة هــذا مــا ظهــر لــي وبــه‬\n‫حكمــت ألجــل احلــق العــام وجــرى نصــح املدعــى عليــه مبــا يناســب املقــام‬\n‫وبإعــان احلكــم علــى املدعــى عليــه قــرر قناعتــه بــه وأبدى املدعــي العام‬\n‫اعتراضــه عليــه وطلــب رفعــه الــى محكمــة االســتئناف واســتعد بتقــدمي‬\n‫الئحــة اعتراضيــة فأفهــم مبراجعتنــا يــوم االربعــاء ‪1434/07/19‬ه ـ‬\n‫الســتالم نســخة احلكــم وتقــدمي اعتراضــه عليــه خــال ثالثــون يومـ ًا مــن‬\n‫تاريــخ االســتالم وإن لــم يتقــدم باعتراضــه خاللهــا فيســقط حقــه يف‬\n‫االعتــراض وأقفلــت اجللســة يف متــام الســاعة العاشــرة والنصــف صباح ـ ًا‬\n‫وعلــى مــا تقــدم حصــل التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n                                                                                       ‫‪122‬‬\n\f                                     ‫وصحبــه وســلم حــرر يف ‪1434/07/15‬ه ـ ـ ‪.‬‬\n      ‫احلمــدهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪-:‬‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف مبكــة‬\n      ‫املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة‬\n      ‫بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بجــدة رقــم (‪)34911643‬‬\n      ‫وتاريــخ ‪ 1434/10/26‬ه ـ املرفــق بهــا القــرار رقــم (‪ )34268577‬وتاريــخ‬\n      ‫‪ 1434/7/15‬ه ـ الصــادر مــن فضيلــة القاضــي ‪ ........‬باحملكمة اجلزائية‬\n      ‫بجــدة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪ ...........‬تشــادي اجلنســية‪،‬‬\n      ‫املتهــم يف مخــدرات احملكــوم فيــه مبــادون باطنــه‪ ،‬وبدراســة القــرار‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تققــرت املوافقــة علــى احلكــم ‪،‬‬\n      ‫واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪123‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":117,"source_page_end":123,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"105b8d3e22ff7716839f4f1466c349287ece383e105186db7b8375c384753774","normalized_text_hash":"a16a9951179bfd2be87a1c29f572c4b7d140332a274c8dcd2a6c4ed17970de8e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p117-34268577"},{"id":"2c75a1e5-ee96-5fdc-8fd8-f6c3e4609995","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد التعاطي والترويج -قات -وجود سابقة -التعزير بالسجن واجللد والغرامة واملصادرة وإسقاط شريحة","document_number":"34193905","case_number":"34177079","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/21","year":"1434","subject":"مخدرات -حيازة بقصد التعاطي والترويج -قات -وجود سابقة -التعزير بالسجن واجللد والغرامة واملصادرة وإسقاط شريحة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34193905 :‬تاريخه‪1434/4/21 :‬هـ‬\n                    ‫رقم القضية‪34177079 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34231343‬تاريخه‪1434/6/5:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة بقصــد التعاطــي والترويــج ‪ -‬قــات ‪ -‬وجــود ســابقة‬\n ‫‪ -‬التعزيــر بالســجن واجللــد والغرامــة واملصــادرة وإســقاط شــريحة‬\n                                                                  ‫جــوال‪.‬‬\n\n\n\n ‫املادتــن الثالثــة والرابعــة مــن قــرار وزيــر الداخليــة رقــم ‪ 2057‬مــن‬\n                                                          ‫‪1404/5/26‬ه ـ ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة نبــات القــات احملظــور‬\n ‫بقصــد الترويــج والتعاطــي وتعاطيــه وبيعــه وطلــب املدعــي العــام إثبــات‬\n ‫مــا اســند إليــه واحلكــم عليــه بعقوبــة الســجن والغرامــة ومصــادرة‬\n ‫الهاتــف اجلــوال وإســقاط شــريحته املســتخدم يف اجلرميــة ‪،‬حيــث إنــه‬\n ‫مت القبــض علــى املدعــى عليــه بعــد إخباريــة مفادهــا إن املدعــى عليــه‬\n ‫يقــوم بترويــج القــات فتــم التنســيق بــن املصــدر واملــروج وتقابــا يف‬\n ‫املوقــع احملــدد وقبــض علــى املــروج بعــد عمليــة االســتالم والتســليم ‪،‬أقـ ّـر‬\n ‫املدعــى عليــه بالدعــوى‪ ،‬وجــود ســابقة علــى املدعــى عليــه‪ ،‬بنــاء علــى‬\n ‫مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد‬\n ‫والغرامــة ومصــادرة الهاتــف اجلــوال املســتخدم يف اجلرميــة وإســقاط‬\n\n                                                                                        ‫‪124‬‬\n\f                         ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n                                                                ‫شــريحته ُ‬\n\n\n\n      ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد لدي أنا ‪.....‬‬\n      ‫القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n      ‫فضيلة رئيس احملكمة اجلزائية يف محافظة ‪ ............‬برقم ‪34177079‬‬\n      ‫وتاريــخ ‪1434/04/17‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34945721‬وتاريــخ‬\n      ‫‪1434/04/17‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/04/21‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 : 45‬وفيهــا قــدم املدعــي العــام ‪ ......‬الئحــة دعــوى‬\n      ‫ا فيهــا‬ ‫عامــة ضــد ‪ ........‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ .....‬قائـ ً‬\n      ‫باالطــاع علــى محضــر االنتقــال و القبــض والتفتيــش املعــد مــن قبــل‬\n      ‫رجــال الضبــط اجلنائــي بشــعبة مكافحــة املخــدرات بالدمــام تبني أنه يف‬\n      ‫يــوم األحــد املوافــق ‪1434/2/17‬ه ـ ورد بــاغ مــن أحــد املصــادر الســرية‬\n      ‫عــن شــخص يدعــى (‪ ).....‬يقــوم بترويــج القــات املخــدر ويســتخدم هاتفــه‬\n      ‫اجلــوال رقــم (‪ )....‬فتــم متكــن املصــدر مــن االتصال عليــه وطلب منه قات‬\n      ‫مببلــغ (‪ )700‬ســبعمائة ريــال فــرد املــروج أنهــا موجــودة وســيحضر إلــى‬\n      ‫شــقة املصــدر فتــم تزويــد املصــدر مببلــغ مرقــم وتكليــف أحــد أعضــاء‬\n      ‫الفــر قــه القابضــة مبرافقــة املصــدر وباقــي أعضــاء الفرقــة القابضــة‬\n      ‫كان تواجدهــم خــارج شــقة املصــدر للمراقبــة وبعــد نصــف ســاعة حضر‬\n      ‫شــخص يحمل معه كيس ودخل شــقه املصدر وبعد دقائق أعطى رجل‬\n      ‫األمــن املرافــق للمصــدر إشــارة االســتالم والتســليم ومت مداهمــة الشــقة‬\n      ‫والقبــض علــى املــروج والــذي اتضــح انــه املتهــم املذكــور وأن مــا قــام‬\n      ‫بترويجــه هــو حزمــة مــن نبــات القــات احملظــور بلــغ وزنــه (‪ )446‬أربعمائــة‬\n\n‫‪125‬‬\n\f‫وســتة وأربعــون جرامـ ًا وبتفتيــش الكيــس الــذي كان يحملــه عثــر علــى‬\n‫عــدة حــزم خضــراء اللــون بلــغ وزنهــا جميعــا (‪ )800‬ثمامنائــة جــرام وأفــاد‬\n‫للجهــة القابضــة أنــه يحتــاز باقــي الكميــة يف منزلــه وباالنتقــال ملنزلــه‬\n‫عثــر يف جهــاز التبريــد علــى عــدة حــزم خضــراء اللــون بلــغ وزنهــا جميعــا‬\n‫(‪ ()8916‬ثمانيــة آالف وتســعمائة وســتته عشــر جــرام وبتفتيشــه عثــر‬\n‫معــه علــى املبلــغ املرقــم كمــا عثــر معــه علــى جــوال يحمــل نفــس الرقــم‬\n‫الــذي مت عليــه التنســيق أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪906‬‬\n‫ك ش) وتاريــخ ‪1434/2/26‬ه ـ أن مــا مت ضبطــه للترويــج واحليازة بقصد‬\n‫االســتخدام إنهــا لنبــات القــات احملظــور واملــدرج باجلــدول األول رقــم (‪)4‬‬\n‫الفقــرة رقــم (‪ )5‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة مت‬\n‫إيقــاف املتهــم املذكــور بالســجن رهــن احملاكمــة لكــون جرميتــه مــن‬\n‫اجلرائــم الكبيــرة املوجبــة لإليقــاف وفقـ ًا للقــرار الــوزاري رقــم (‪)1900‬‬\n‫وتاريــخ ‪1428/7/9‬ه ـ وباســتجوابه اقــر ببيعــه مــا وزنــه (‪ )446‬أربعمائــة‬\n‫وســتة وأربعــون جرام ـ ًا مــن نبــات القــات احملظــور وبحيازتــه مــا وزنــه‬\n‫(‪ )800‬ثمامنائــة جــرام و(‪ ()8916‬ثمانيــة آالف وتســعمائة وســتة عشــر‬\n‫جــرام بقصــد التعاطــي وتعاطيــه لــه وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n‫ل ـ ‪ .... :‬باالتــي‪ -1‬ببيــع مــا وزنــه (‪ )446‬أربعمائــة وســتة وأربعــون جرامـ ًا‬\n‫مــن نبــات القــات احملظــور بقصــد االجتــار ‪ -2‬حيازتــه مــا وزنــه (‪)9716‬‬\n‫تســعة االف وســبعمائة وســتة عشــر جرام ـ ًا بقصــد التعاطــي وتعاطيــه‬\n‫لــه وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬اعترافــه مبــا نــوه عنــه املــدون‬\n‫مبحضــر اســتجوابه املرفــق علــى اللفــات رقــم (‪ -2)13‬محضــر القبــض‬\n‫والتفتيــش املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪)12‬املرفــق علــى‬\n‫اللفــة رقــم (‪ -3)1‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى‬\n\n\n                                                                                      ‫‪126‬‬\n\f                                                                          ‫اللفــة رقــم (‪.)19‬‬\n      ‫‪ -4‬ضبــط املبلــغ املرقــم والهاتــف النقــال املســتخدم يف عمليــة البيــع‬\n      ‫مــع املتهــم املذكــور دليــل علــى عمليــة البيــع وحيــث أن مــا أقــدم عليــه‬\n      ‫املذكــور وهــو بكامــل أهليتــه املعتبــرة محــرم شــرعا ومعاقــب عليــه‬\n      ‫شــرعا ونظامــا أطلــب مــا يلــي أوالً‪ :‬إثبــات مــا أســند إليــه وفق ـ ًا للقــرار‬\n      ‫رقــم (‪ )11‬يف ‪1374/02/01‬ه ـ واحلكــم عليــه بعقوبــة الســجن والغرامــة‬\n      ‫الــواردة بالفقــرة رقــم (‪ )3‬بالقــرار رقــم (‪ )11‬بتاريــخ ‪1374/02/01‬ه ـ‬\n      ‫واملعــدل بقــرار وزيــر الداخليــة رقــم (‪ )2057‬لعــام ‪1404‬ه ـ لقــاء بيعــه‬\n      ‫للقــات املخــدر واحملظــور وتعاطيــه لــه ثانيــا‪ :‬مصــادرة الهاتــف اجلــوال‬\n      ‫العائــد للمذكــور مــن نــوع يحمــل الرقــم (‪)........................‬الســتخدامه‬\n      ‫يف بيــع نبــات القــات احملظــورة وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n      ‫(‪ )53‬مــن النظــام ‪ ،‬مــع املطالبــة بإســقاط شــريحة الهاتــف النقــال‬\n      ‫وعــدم صرفهــا لنفــس املتهــم وفقــا لتعميــم ســمو وزيــر الداخليــة رقــم‬\n      ‫(‪ )9798‬وتاريــخ ‪1429/2/10-9‬ه ـ هــذه دعــواي وبســؤال املدعــى عليــه‬\n      ‫عــن الدعــوى أجــاب بقولــه مــا جــاء يف الدعــوى كلــه صحيــح ففــي‬\n      ‫تاريــخ ‪1434/2/17‬ه ـ ورد اتصــال علــى هاتفــي اجلــوال نــوع ‪ .....‬ورقــم‬\n      ‫جوالــي هــو (‪ )................‬وكان املتصــل يطلــب منــي أن أبيعــه نبــات‬\n      ‫القــات احملظــور مببلــغ ســبعمائة ريــال فوافقــت علــى ذلــك وأخبــرت‬\n      ‫املتصــل بأنــي ســوف أحضــر لــه يف شــقته ومعــي نبــات القــات وانتهــت‬\n      ‫املكاملــة وبالفعــل حضــرت للمتصــل يف شــقته يف نفــس يــوم االتصــال‬\n      ‫بعــد صــاة العشــاء وقمــت ببيعــه نبــات القــات احملظــور حيــث أعطانــي‬\n      ‫املشــتري مبلــغ ســبعمائة ريــال وســلمته مــا وزنه(‪)446‬أربعمائــة وســتة‬\n      ‫وأربعــون جرام ـ ًا مــن نبــات القــات احملظــور وبعدهــا حضــر رجــال‬\n\n\n‫‪127‬‬\n\f‫املكافحــة وقبضــوا علــي داخــل الشــقة ووجــدوا معــي عــدة حــزم مــن‬\n‫نبــات القــات احملظــور مجمــوع وزنهــا هو(‪)800‬ثمامنائــة جــرام وهــي‬\n‫تعــود لــي بقصــد االســتعمال كمــا أنــي أخبرتهــم بوجــود نبــات القــات‬\n‫احملظــور يف شــقتي فذهبــوا لشــقتي ووجــدوا عــدة حــزم خضــراء مــن‬\n‫نبــات القــات احملظــور بلــغ وزنهــا (‪)8916‬ثمانيــة االف وتســعمائة وســتة‬\n‫عشــر جرام ـ ًا وهــي تعــود لــي بقصــد االســتعمال فأنــا اســتعمل القــات‬\n‫احملظــور هــذا مــا حصــل ويوجــد لــدي ســابقة ترويــج القــات وأنــا نــادم‬\n‫علــى فعلــي هكــذا أجــاب بعــد ذلــك جــرى الرجــوع إلــى اللفــة رقــم(‪)9‬‬\n‫وتضمنــت محضــر التحريــز وجــاء فيــه وزن الكميــة املروجــة والكميــة‬\n‫احملــازة وهــو كمــا ذكــر املدعــي العــام يف دعــواه كمــا جــرى الرجــوع‬\n‫إلــى اللفــة رقم(‪)22‬وتضمنــت التقريــر الكيمــاوي الشــرعي وهــو كمــا‬\n‫ذكــر املدعــي العــام يف دعــواه بعــد ذلــك جــرى االطــاع علــى صــورة‬\n‫القــرار الشــرعي املرفــق لفــه رقم(‪)26‬الصــادر بحــق املدعــى عليــه برقــم‬\n‫‪ 55/4‬يف ‪1431/2/15‬ه ـ مــن احملكمــة اجلزائيــة ‪ ............‬حيــث ثبــت‬\n‫قيــام املدعــى عليــه ببيــع مائتــن وثالثــون جرام ـ ًا مــن القــات احملظــور‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه‬   ‫فبنـ ً‬\n‫بقيامــه ببيــع القــات احملظــور مســتخدم ًا هاتفــه اجلــوال يف ذلــك كمــا‬\n‫أقــر بحيازتــه القــات احملظــور بقصــد االســتعمال واســتعماله القــات‬\n‫احملظــور وحيــث إن للمدعــى عليــه ســابقة يف ترويــج القــات احملظــور‬\n‫كمــا أن الكميــه احملــازة كبيــرة وملــا جــاء يف محضــر التحريــز‬\n‫والتقريــر الكيمــاوي الشــرعي وملــا جــاء يف املادتــن الثالثــة والرابعــة‬\n               ‫مــن قــرار وزيــر الداخليــة رقــم ‪ 2057‬يف ‪1404/5/26‬ه ـ ‪.‬‬\n‫لــذا فقــد قــررت مــا يلــي أو ًال ثبــت لــدي قيــام املدعــى عليــه بترويــج مــا‬\n\n\n                                                                                        ‫‪128‬‬\n\f      ‫وزنــه (‪ )446‬أربعمائــة وســتة وأربعــون جرامـ ًا مــن نبــات القــات احملظــور‬\n      ‫عــن طريــق البيــع مببلــغ ســبعمائة ريــال وقــررت تعزيــره لقــاء ذلــك بســجنه‬\n      ‫مــدة ثــاث ســنوات اعتبــار ًا مــن تاريــخ إيقافــه وتغرميــه مبلــغ عشــرة االف‬\n      ‫ريــال ‪10000‬ثانيـ ًا ثبــت لــدي حيــازة املدعــى عليــه مــا وزنه(‪)9716‬تســعة‬\n      ‫االف وســبعمائة وســتة عشــر جرام ـ ًا مــن نبــات القــات احملظــور بقصــد‬\n      ‫االســتعمال وعقوبتــه التعزيريــة علــى ذلــك داخلــه يف عقوبتــه التعزيريــة‬\n      ‫املشــار لهــا بالفقــرة أو ًال ثالث ـ ًا ثبــت لــدي اســتعمال املدعــى عليــه لنبــات‬\n      ‫القــات احملظــور وقــررت تعزيــره لقــاء ذلــك بجلــده ســبعني جلــده علــى‬\n      ‫دفعتــن متســاويتني بينهمــا مــدة ال تقــل عــن عشــرة أيــام رابعـ ًا مصــادرة‬\n      ‫الهاتــف اجلــوال العائــد للمدعــى عليــه املســتخدم يف الترويــج وإســقاط‬\n      ‫الشــريحة وعــدم صرفهــا للمدعــى عليــه ومبــا تقــدم حكمــت وبعــرض‬\n      ‫احلكــم قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام مكتفيـ ًا مبــا قــدم يف‬\n      ‫الئحــة الدعــوى وأقفلــت اجللســة الســاعة الثانيــة عشــر إال ربــع وصلــى اهلل‬\n                                                              ‫وســلم علــى نبينــا محمــد ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة ‪ ............‬علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة ‪ ............‬برقــم‬\n      ‫‪ 34945720‬وتاريــخ ‪1434/4/28‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 34/1084974‬وتاريــخ ‪1434/5/4‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...‬املســجل برقــم ‪34193905‬‬\n      ‫وتاريــخ ‪1434/4/21‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ....‬يف قضيــة‬\n      ‫قــات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه؛‬\n      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n\n\n‫‪129‬‬\n\f‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                    ‫حــرر يف ‪1434/6/4‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                ‫‪130‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":124,"source_page_end":130,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"81a8c138f0d146e77b89a1331ed0e1a651ba8dd49cd647b1ee3a4f6a2fcba1df","normalized_text_hash":"511ae1b5746683d37e40da70c652e3742db408e85a6257a5897ef3994674e75a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p124-34193905"},{"id":"3f66795f-c49e-5fed-9117-47444ee64f1b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -إقرار املدعى عليه بالتعاطي -التعزير بالسجن واجللد -واإلبعاد عن الباد - سقوط جزء من عقوبة السجن بشرط حفظ أجزاء من القرآن","document_number":"34198765","case_number":"34178970","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/27","year":"1434","subject":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -إقرار املدعى عليه بالتعاطي -التعزير بالسجن واجللد -واإلبعاد عن الباد - سقوط جزء من عقوبة السجن بشرط حفظ أجزاء من القرآن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34198765 :‬تاريخه ‪1434/4/27:‬هـ‬\n                         ‫رقم القضية‪34178970:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34210699‬تاريخه‪1434/5/11 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة بقصــد الترويــج والتعاطــي ‪ -‬قــات ‪ -‬إقــرار املدعــى‬\n      ‫عليــه بالتعاطــي‪ -‬التعزيــر بالســجن واجللــد ‪ -‬واإلبعــاد عــن البــاد ‪-‬‬\n      ‫ســقوط جــزء مــن عقوبــة الســجن بشــرط حفــظ أجــزاء مــن القــرآن‬\n                                                                        ‫الكــرمي‪.‬‬\n\n\n\n\n      ‫‪ -1‬املــادة الرابعــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬يف ‪1374/2/1‬ه‬\n      ‫املعــدل بقــراري وزيــر الداخليــة رقــم(‪ )2057‬لعــام ‪ 1404‬ه ـ ورقــم ‪3818‬‬\n                                                                ‫لعــام ‪1410‬ه ـ ‪.‬‬\n                      ‫‪ -2‬األمر السامي الكرمي رقم (‪ )59633‬يف ‪1433/12/9‬هـ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة القــات بقصــد الترويــج‬\n      ‫والتعاطــي وطلــب إثبــات مــا أســند إليــه واحلكــم بتعزيــره وفــق النظــام‪،‬‬\n      ‫حيــث قبــض علــى املدعــى عليــه أثنــاء قيادتــه الســيارة وبتفتيشــه عثــر‬\n      ‫بحوزتــه علــى نبــات القــات وأثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫إيجابيــة العينــة لنبــات القــات احملظــور ‪ .‬مصادقــة املدعــى عليــه علــى‬\n      ‫التعاطــي وليــس الترويــج‪ ،‬وملــا كانــت بينــة املدعــي العــام للترويــج غيــر‬\n      ‫موصلــة ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه‬\n\n‫‪131‬‬\n\f‫بالســجن ســنة وســقوط ثالثــة أشــهر مــن محكوميتــه عنــد حفظــه ثالثــة‬\n‫أجــزاء وجلــده مائــة وخمســن جلــدة مفرقــة علــى دفعــات مقــدار كل‬\n‫دفعــة خمســون جلــدة لقــاء شــبهة الترويــج وإبعــاده عــن اململكــة بعــد‬\n‫انتهــاء محكوميتــه وقنــع املدعــى عليــه واعتــرض املدعــي العــام بــدون‬\n                     ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬    ‫الئحــة ُ‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n‫‪ .....‬القاضــي يف احملكمــة اجلزائيــة بجــازان وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم ‪34178970‬‬\n‫وتاريــخ ‪1434/04/20‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34955837‬وتاريــخ‬\n‫‪1434/04/20‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/04/27‬ه ـ افتتحــت‬\n‫اجللســة الســاعة العاشــرة والنصــف صباحـ ًا وفيهــا حضــر املدعــي العــام‬\n‫‪.....‬املعمــد بالعمــل مبوجــب خطــاب رقــم ‪.....‬وتاريــخ ‪1433/03/22‬ه ـ‬\n‫وحضــر املدعــى عليــه ‪.....‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n‫ا يف دعــواه أنــه‬\n                 ‫(‪ ).....‬وتاريــخ ‪1423/7/18‬ه ـ وادعــى املدعــي العــام قائـ ً‬\n‫بتاريــخ ‪1434/03/8‬ه ـ وأثنــاء قيــام إحــدى دوريــات مركــز املجاهديــن‬\n‫بواجبهــا امليدانــي املعتــاد وأثنــاء تواجــد الفرقــة باملوقــع املســمى مثلــث‬\n‫هــروب مت القبــض علــى املدعــى عليــه أثنــاء قيادتــه لســيارة مــن نــوع‬\n‫صالــون صنــع ‪1998‬م حتمــل اللوحــة رقــم (‪ ).....‬وبتفتيشــه عثــر بحوزتــه‬\n‫علــى كميــة مــن نبــات القــات احملظــور بلــغ وزنهــا خمســة وعشــرون‬\n‫كيلــو جرام ـ ًا أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ ).....‬بتاريــخ‬\n‫‪1434/03/17‬ه ـ إيجابيــة العينــة للقــات احملظــور وباســتجواب املدعــى‬\n\n                                                                                     ‫‪132‬‬\n\f      ‫عليــه أقــر بحيازتــه للكميــة املضبوطــة من نبات القات احملظور وذك ــر‬\n      ‫بأنهــا تعـ ــود لــه وغرضــه منهــا التعاطــي وأنــه حصــل عليهــا مــن شــخص‬\n      ‫مينــي ال يعرفــه مببلــغ ســتمائة ريــال وصــادق علــى أقوالــه حتقيق ـ ًا وقــد‬\n      ‫أســفر التحقيــق معــه عــن توجيــه االتهــام إليــه بحيــازة مــا وزنــه خمســة‬\n      ‫وعشــرون كيلــو جرامـ ًا مــن القــات احملظــور بقصــد الترويــج والتعاطــي‬\n      ‫وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة وحيــث أن مــا‬\n      ‫أقــدم عليــه املدعــى عليــه فعــل محــرم شــرع ًا ومجــرم نظام ـ ًا مبوجــب‬\n      ‫قــرار مجلــس الــوزراء رقــم (‪ )11‬يف ‪1374/2/1‬ه ـ ومــا حلــق بــه مــن‬\n      ‫تعديــات لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره‬\n      ‫يف ضــوء املادتــن (الثالثــة) و (الرابعــة) مــن القــرار الــوزاري املشــار إليــه‬\n      ‫إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/09‬ه ـ‬\n      ‫واحلكــم بإبعــاده إلــى بــاده وذلــك اســتناد ًا لتعميــم ســمو وزيــر الداخليــة‬\n      ‫رقــم ‪ 69935‬وتاريــخ ‪1433/06/18‬ه ـ وبســؤال املدعــى عليــه عمــا جــاء‬\n      ‫ا مــا ذكــره املدعــي العــام مــن اتهامــي‬  ‫بدعــوى املدعــي العــام أجــاب قائـ ً‬\n      ‫بحيــازة مــا وزنــه خمســة وعشــرون كيلــو جرام ـ ًا مــن القــات احملظــور‬\n      ‫بقصــد الترويــج والتعاطــي فهــذا غيــر صحيــح والصحيــح أنهــا للتعاطــي‬\n      ‫فقــط حيــث اشــتريتها مببلــغ قــدره ســتمائة ريــال هكــذا أجــاب ثــم جرى‬\n      ‫ســؤال املدعــي العــام هــل لديــه بينــة علــى كــون املدعــى عليــه قــد حــاز‬\n      ‫ا بينتــي علــى ذلــك هــي كبــر‬    ‫الكميــة لغــرض الترويــج فأجــاب قائ ـ ً‬\n      ‫حجــم الكميــة هكــذا أجــاب وبعــد ســماع الدعــوى واإلجابــة جــرى‬\n      ‫منــي دراســة األوراق واالطــاع علــى محضــر القبــض املرفــق باملعاملــة‬\n      ‫فوجدتــه يتضمــن القبــض علــى املدعــى عليــه وبحوزتــه الكميــة‬\n      ‫املذكــورة يف الدعــوى مــن القــات احملظــور ولــم أجــد مــا يثبــت حيازتــه‬\n\n\n‫‪133‬‬\n\f‫للكميــة لغــرض الترويــج ثــم جــرى االطــاع علــى صحيفــة ســوابق‬\n‫املدعــى عليــه فوجــدت أنــه ال توجــد ســوابق مســجلة عليــه ثــم جــرى‬\n‫االطــاع علــى التقريــر الكيميائــي الشــرعي املرفــق باملعاملــة فوجدتــه‬\n‫ـاء علــى ما تقدم مــن الدعوى‬  ‫يتضمــن إيجابيــة العينــة للقــات احملظــور فبنـ ً‬\n‫واإلجابــة وحيــث أقــر املدعــى عليــه بحيازتــه للكميــة املذكــورة يف‬\n‫الدعــوى مــن القــات احملظــور بقصــد التعاطــي وأنكــر الترويــج وحيــث‬\n‫أن بينــة املدعــي العــام غيــر موصلــة علــى كــون املدعــى عليــه قــد حــاز‬\n‫الكميــة لغــرض الترويــج وذلــك لعــدم كفايــة األدلــة ضــده وحيــث‬\n‫توجهــت شــبهة الترويــج ضــد املدعــى عليــه وذلــك نظــر ًا لكبــر حجــم‬\n‫الكميــة وحيــث ال توجــد ســوابق مســجلة عليــه وحيــث أثبــت التقريــر‬\n‫الكيميائــي الشــرعي إيجابيــة العينــة للقــات احملظــور ولــكل مــا تقــدم‬\n                                   ‫فقــد حكمــت مبــا يلــي أو ًال ‪ /‬ثبــت لـ ّ‬\n‫ـدي إدانــة املدعــى عليــه بحيــازة‬\n‫مــا وزنــه خمســة وعشــرون كيلــو جرام ـ ًا مــن القــات احملظــور بقصــد‬\n‫التعاطــي ومبوجــب ذلــك صرفــت النظــر عــن طلــب املدعــي العــام بتعزيــر‬\n‫املدعــى عليــه وفقـ ًا للمــادة الثالثــة وذلــك لعــدم ثبــوت الترويــج لــدي ثانيـاً‪/‬‬\n‫حكمــت عليــه بالســجن ملــدة ســنة تبــدأ مــن تاريــخ دخولــه الســجن علــى‬\n‫ذمــة هــذه القضيــة وذلــك اســتناد ًا للمادة الرابعة من قــرار مجلس الوزراء‬\n‫رقــم (‪ )11‬يف ‪1374/2/1‬ه ـ املعــدل بقــراري ســمو وزيــر الداخليــة رقــم‬\n‫(‪ )2057‬يف ‪1404/5/26‬ه ـ ورقــم (‪ )3818‬يف ‪1410/9/28‬ه ـ إنفــاذ ًا‬\n‫لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬هـ ويســقط‬\n‫عــن املدعــى عليــه ثالثــة أشــهر مــن محكوميتــه وذلــك عنــد حفظــه‬\n‫لثالثــة أجــزاء مــن القــرآن حفظـ ًا متقنـ ًا بعــد اختبــار يجــرى لــه مــن قبــل‬\n‫اجلهــة املختصــة ثالث ـ ًا ‪ /‬حكمــت بجلــده مائــة وخمســن جلــدة مفرقــة‬\n\n\n                                                                                           ‫‪134‬‬\n\f      ‫علــى دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة واألخــرى مــدة‬\n      ‫ال تقــل عــن خمســة عشــر يوم ـ ًا وذلــك لقــاء توجــه شــبهة الترويــج ضــده‬\n      ‫نظــر ًا لكبــر حجــم الكميــة رابع ـ ًا ‪ /‬حكمــت بإبعــاده عــن اململكــة‬\n      ‫بعــد انتهــاء محكوميتــه وذلــك اســتناد ًا للمــادة الرابعــة مــن قــرار مجلــس‬\n      ‫الــوزراء رقــم (‪ )11‬يف ‪1374/2/1‬ه ـ املعــدل بقراري ســمو وزير الداخلية‬\n      ‫رقــم (‪ )2057‬يف ‪1404/5/26‬ه ـ ورقــم (‪ )3818‬يف ‪1410/9/28‬ه ـ‬\n      ‫إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ‬\n      ‫وبعــرض احلكــم علــى املدعــى عل ــيه قــرر القناعــة باحلكــم كمــا قــرر‬\n      ‫املدعــي العــام االعتــراض علــى احلكــم بــدون تقــدمي الئحــة اعتراضيــة‬\n      ‫عليــه قــررت رفــع املعاملــة حملكمــة االســتئناف حســب التعليمــات‬\n      ‫وقــد جــرى النطــق باحلكــم يف الســاعة احلاديــة عشــرة صباح ـ ًا بتاريــخ‬\n      ‫‪1434/04/27‬ه ـ وصلــى اهلل علــى س ــيدنا محمــد وآلــه وصحبــه وســلم‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائية بجازان برقــم ‪34955837‬‬\n      ‫وتاريــخ ‪1434/4/29‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضي‬\n      ‫باحملكمــة الشــيخ ‪ .....‬برقــم ‪ 34198765‬وتاريــخ ‪1434/4/27‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد ‪ -.....‬مينــي اجلنســية ‪ -‬يف قضيــة‬\n      ‫( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n      ‫املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                                  ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n‫‪135‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":131,"source_page_end":135,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"698bfac323f4bb814652e6ab0cd8f63e2c08c7c529ea921373cb4972e391362d","normalized_text_hash":"a124941aca83a398194146665552236a8c08e17ae99c071de1cc5d5548a3a9fe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p131-34198765"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"b2b6e305-8989-5e21-a284-70b9d0a43ecd","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة -تستر -هروب من الفرقة القابضة -اعتراف حتقيق ا -تعزير بالسجن واملنع من السفر - عدم التقيد بالوصف الوارد يف الئحة الدعوى وإعطاء المحكمة الفعل الوصف الذي يستحقه .","document_number":"34198256","case_number":"34167081","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/27","year":"1434","subject":"مخدرات -حيازة حبوب محظورة -تستر -هروب من الفرقة القابضة -اعتراف حتقيق ا -تعزير بالسجن واملنع من السفر - عدم التقيد بالوصف الوارد يف الئحة الدعوى وإعطاء المحكمة الفعل الوصف الذي يستحقه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34198256:‬تاريخه‪1434/4/27:‬هـ‬\n                        ‫رقم الدعوى‪34167081:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34244052‬تاريخه‪1434/06/18 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة حبــوب محظــورة ‪ -‬تســتر‪ -‬هــروب مــن الفرقــة‬\n      ‫القابضــة ‪ -‬اعتــراف حتقيق ـ ًا‪ -‬تعزيــر بالســجن واملنــع مــن الســفر ‪-‬‬\n      ‫عــدم التقيــد بالوصــف الــوارد يف الئحــة الدعــوى وإعطــاء احملكمــة‬\n                                           ‫الفعــل الوصــف الــذي يســتحقه ‪.‬‬\n\n\n\n                      ‫املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n      ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه بحيــازة احلبــوب احملظــورة‬\n      ‫لغيــر قصــد الترويــج أو التعاطــي أو االســتخدام وتســتره علــى مصــدر‬\n      ‫احلبــوب وهروبــه مــن الفرقــة القابضــة‪ ،‬وطلــب املدعــي العــام إثبــات مــا‬\n      ‫أســند إليــه واحلكــم عليــه بالعقوبــة الــواردة يف املــادة (‪ )39‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة ومنعــه مــن الســفر وعقوبــة‬\n      ‫تعزيريــة لقــاء تســتره علــى مصــدر املخــدرات وهروبــه مــن الفرقــة‬\n      ‫القابضــة ‪ ،‬مت القبــض علــى املدعــى عليــه حيــث كان عاكسـ ًا للســير‬\n      ‫علــى ســيارته فتــم اســتيقافه فرمــى كيــس بداخلــه (‪ )14‬حبــة يشــتبه‬\n      ‫أن تكــون محظــورة ثــم الذ بالفــرار فتــم التعميــم عنــه و القبــض عليــه‪،‬‬\n      ‫وصــدر التقريــر الكيميائــي بإيجابيــة العينــة املرســلة‪ ،‬أقــرار املدعــى‬\n\n‫‪101‬‬\n\f‫عليــه باحليــازة ألجــل االســتخدام‪ ،‬ثبــوت إدانــة املدعــى عليــه باحليــازة‬\n‫ألجــل االســتخدام‪ ،‬تعزيــر املدعــى عليــه بالســجن واملنــع مــن الســفر‪،‬‬\n                               ‫تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬املــازم القضائــي يف احملكمــة‬\n‫اجلزائيــة باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                                            ‫ّ‬\n‫احملكمــة اجلزائيــة يف محافظــة االحســاء املكلــف برقــم ‪34167081‬‬\n‫وتاريــخ ‪1434/04/13‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34891311‬وتاريــخ‬\n‫‪1434/04/13‬ه ـ وبنــاء علــى تعميــدي مــن فضيلــة القاضــي ‪.........‬‬\n‫باخلطــاب رقــم ‪ 331633101‬يف ‪1433/8/17‬ه ـ ففــي يــوم اإلثنــن‬\n‫املوافــق‪ 1434/04/22‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 00‬وفيهــا‬\n‫حضــر املدعــي العــام ‪ .........‬وحضــر حلضــوره املدعــى عليــه‪ .........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .........‬وفيهــا ادعــى املدعــي‬\n‫قائــا يف دعــواه أنــه باالطــاع علــى محضــر القبــض رقــم (‪).........‬‬\n‫وتاريــخ ‪1434/2/13‬ه ـ ا ُملعــد مــن قبــل دوريــات األمــن باالحســاء تبــن‬\n‫أنــه مت االشــتباه بســيارة نــوع (‪ )........‬صنــع ‪2001‬م حتمــل اللوحــة رقــم‬\n‫(‪ ).........‬لونهــا فضــي بقيــادة املتهــم لســيره باجتــاه عكــس الطريــق‬\n‫وبعــد اســتيقافه رمــى كيــس بداخلــه عــدد (‪ )14‬حبــة يشــتبه أن تكــون‬\n‫محظــورة ثــم الذ بالفــرار ومت التعميــم عليــه والقبــض عليــه بتاريــخ‬\n‫‪1434/2/15‬هــ‪ .‬وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪).........‬‬\n‫لعــام ‪1434‬ه ـ إيجابيــة عينــة مــا مت ضبطــه ملــادة اإلمفيتامــن و املــدرج يف‬\n‫اجلــدول (‪ )2‬فئــة (ب) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n                                                                                     ‫‪102‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":101,"source_page_end":102,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dd1cd56f5c66b628df8e55b0fe7e58fac724d7a42e9069a038dbe9fc3be87040","normalized_text_hash":"817f2b093ec19eb0407d0db97f178c03d9a5cd31a1cb4f0e620a86052d3f30b1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p101-34198256"},{"id":"7eaf3f65-437d-5479-a950-3ce137c58b41","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها وتستر على مصدرها -محاولة إدخال مخدر إلى السجن -إقرار -إدانة - التعزير بالسجن واجللد واملنع من السفر ..","document_number":"34193641","case_number":"34167643","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/21","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها وتستر على مصدرها -محاولة إدخال مخدر إلى السجن -إقرار -إدانة - التعزير بالسجن واجللد واملنع من السفر ..","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34193641:‬تاريخه ‪1434/04/21:‬هـ‬\n                  ‫رقم الدعوى ‪34167643:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 341095246‬تاريخه‪1434/06/13:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيهــا وتســتر‬\n‫علــى مصدرهــا‪ -‬محاولــة إدخــال مخــدر إلــى الســجن‪ -‬إقــرار‪ -‬إدانــة ‪-‬‬\n                         ‫التعزيــر بالســجن واجللــد واملنــع مــن الســفر ‪..‬‬\n\n\n\n\n   ‫‪ -1‬املواد (‪ )41‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n                          ‫‪ -2‬املادة (‪ )29‬من نظام السجن والتوقيف‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيازتــه احلبــوب احملظــورة‬\n‫احملتويــة علــى اإلمفيتامــن والكلونازيبــام بقصــد التعاطــي وتعاطيــه‬\n‫لهــا ومحاولتــه إدخالهــا للتوقيــف وتســتره علــى مصــدر املخــدر‪،‬‬\n‫واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحة‬\n‫املخــدرات واملؤثــرات العقليــة وبعقوبــة الســجن الــواردة يف نظــام الســجن‬\n‫والتوقيــف‪ ،‬حيــث إنــه مت تفتيــش الســيارة التــي يقودهــا فعثــر فيهــا علــى‬\n‫حبــوب الكلونازيبــام احملظــورة وأثنــاء تفتيشــه شــخصي ًا قبــل إدخالــه‬\n‫إلــى التوقيــف عثــر يف مالبســه الداخليــة علــى حبــوب اإلمفيتامــن‬\n‫احملظــورة‪ ،‬وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة‬\n‫املرســلة لإلمفيتامــن والكلونازيبــام احملظوريــن‪ ،‬أقــر أمــام احملكمــة‬\n\n                                                                                   ‫‪106‬‬\n\f      ‫مبــا أســنده إليــه املدعــي العــام‪ ،‬فقضــت احملكمــة بإدانــة املدعــى عليــه‬\n      ‫بجميــع مــا نســب إليــه وقــررت جلــده ســبعني جلــدة لتعاطــي احلبــوب‬\n      ‫احملظــورة وســجنه ملــدة ســتة شــهر ومنعــه مــن الســفر خــارج اململكــة‬\n      ‫ملــدة ســنتني حليــازة احلبــوب احملظــورة بقصــد التعاطــي وســجنه ملــدة ســتة‬\n      ‫شــهر حملاولتــه إدخالهــا للتوقيــف وتســتره علــى مصــدر املخــدر‪ -‬قنــع‬\n      ‫املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬وقــررت محكمــة‬\n                                            ‫االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 34167643‬وتاريــخ ‪ 1434/04/13‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34894077‬وتاريــخ ‪ 1434/04/13‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافــق‪ 1434/04/20‬ه ـ افتتحــت اجللســة الســاعة ‪09 :15‬‬\n      ‫وفيهــا قــدم املدعــي العــام ‪ /‬الئحــة دعــوى عامــة ضــد ‪ /‬املدعــى عليــه‬\n      ‫‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬حيــث‬\n      ‫إنــه بتاريــخ ‪1434/2/23‬ه ـ قبــض علــى املذكــور مــن قبــل إحــدى‬\n      ‫فــرق دوريــات األمــن أثنــاء قيــام الفرقــة بعملهــا بحــي ‪........‬حيــث‬\n      ‫اشــتبهت الفرقــة بســيارة مــن نــوع (‪ )....‬تســير بــدون لوحــات بقيــادة‬\n      ‫املذكــور ‪ ،‬وباســتيقافه وتفتيــش الســيارة وجــد علــى املرتبــة اخللفيــة‬\n      ‫شــنطة يدويــة بداخلهــا(‪ )14‬أربعــة عشــر حبــة يشــتبه ان تكــون مــن‬\n      ‫حبــوب ( الــروش ) احملظــورة ووجــد لوحــات عائــدة لســيارات وجهــاز‬\n      ‫تابــع لشــركة ‪( .................‬جــرى معاجلــة ذلــك مــن قبــل شــرطة ‪........‬‬\n\n‫‪107‬‬\n\f‫مبوجــب خطابهــم رقــم (‪ )........‬وتاريخ‪1434/2/24‬ه ـ ) واثنــاء تفتيشــه‬\n‫قبــل ادخالــه توقيــف مكافحــة املخــدرات بشــرق الريــاض عثــر بداخــل‬\n‫مالبســه الداخليــة (‪ )17‬ســبع عشــرة حبــة وأربعــه أنصــاف حتمــل عالمــة‬\n‫الكبتاجــون احملظــور جــرى مخاطبــة مكافحــة املخــدرات بشــرق‬\n‫الريــاض باخلطــاب رقــم (‪ )........‬وتاريــخ ‪1434/4/3‬ه ـ إلحالــة مــا يتعلــق‬\n‫بقيــادة املذكــور لســيارة بــدون لوحــات للجهــة املختصــة‪ .‬وقــد أثبــت‬\n‫التقريــران الكيميائيــان الشــرعيان الصــادران مــن مركــز مراقبــة‬\n‫الســموم والكيميــاء الطبيــة الشــرعية بالريــاض املرفقــان رقــم (‪)........‬‬\n‫ورقــم (‪ )........‬لعــام ‪1434‬ه ـ احتــواء احلبــوب التــي حتمــل عالمــة الــروش‬\n‫لعقــار ( كلونازيبــام) وهــو مــن املــواد املهدئــة املدرجــة باجلــدول رقــم (‪)2‬‬\n‫فئــة (د) مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة‪ .‬واحتــواء‬\n‫عينــة احلبــوب املضبوطــة يف مالبســه الداخليــة لإلمفيتامــن وهــو مــن‬\n‫املــواد املنبهــة واملدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وبســماع أقــوال األول األوليــة‬\n‫اقــر بعائديــة حبــوب الكبتاجــون املضبوطــة لــه بقصــد التعاطــي وافــاد‬\n‫ان حبــوب الــروش املضبوطــة تعــود ألخيــه وباســتجوابه أقــر بعائديــة‬\n‫جميــع مــا ضبــط لــه احلبــوب بقصــد التعاطــي وتعاطيــه إياهــا وأفــاد‬\n‫أنــه حصــل عليهــا مــن شــخص مينــي اجلنســية وانــه ال عالقــة ألخيــه مبــا‬\n‫ضبــط معــه حيــث انــه مــن اخلــوف واالرتبــاك ذكــر اســم اخيــه اثنــاء‬\n‫ســماع اقوالــه مبكافحــة املخــدرات‪ .‬وقــد اســفرت اجــراءات التحقيــق‬\n‫عــن توجيــه االتهــام الــى ‪/‬املدعــى عليــه بحيــازة (‪ )14‬اربعــة عشــر حبــة‬\n‫حتــوي عقــار الكلونازيبــام املهــدئ احملظــور و(‪ )17‬ســبعة عشــرة حبــة‬\n‫وأربعــة انصــاف احلبــة مــن حبــوب اإلمفيتامــن املنبــه احملظــور بقصــد‬\n\n\n                                                                                      ‫‪108‬‬\n\f      ‫التعاطــي وتعاطيــه احلبــوب احملظــورة املجــرم مبوجــب املــادة (الثالثــة)‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ومحاولتــه ادخــال حبــوب‬\n      ‫محظــورة لتوقيــف مكافحــة املخــدرات بشــرق الريــاض املعاقــب علــى‬\n      ‫ذلــك مبوجــب املــادة (‪ )29‬مــن نظــام الســجن والتوقيف الصادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )31/‬وتاريــخ ‪1398/6/21‬ه ـ وتســتره عــن مصــدر مــا‬\n      ‫ضبــط املعاقــب علــى ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬مــا‬\n      ‫تضمنــه اعترافــه مبحضــر اســتجوابه املنــوه عنــه واملــدون علــى اللفــات‬\n      ‫رقــم (‪ 18‬ـ‪ -2 ) 20‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة‬\n      ‫املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ ) 2‬مــن ملــف ضبــط اجــراءات‬\n      ‫قضيــة مخــدرات لفــه رقــم(‪ -3 )7‬مــا تضمنــه محضــر القبــض مــن وقائــع‬\n      ‫املنــوه عنــه واملرفــق لفــة رقــم (‪ -4 .) 1،2‬مــا تضمنــه محضــر التفتيــش‬\n      ‫املعــد مــن مكافحــة املخــدرات املنــوه عنــه واملرفــق لفــة رقــم (‪-5 .)10‬‬\n      ‫مــا تضمنــه التقريــران الكيميائيــان الشــرعيان املنــوه عنهمــا املرفقــان‬\n      ‫علــى اللفتــن رقــم (‪ .)26،27‬وحيــث إن مــا أقــدم عليــه املذكــور فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا اطلــب اثبــات ادانتــه مبــا أســند‬\n      ‫إليــه واحلكــم باآلتــي‪1 :‬ـ بالعقوبــة الــواردة يف الفقــرة (األولــى) مــن املــادة‬\n      ‫(‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واملــادة (‪)30‬‬\n      ‫مــن الالئحــة التنفيذيــة للنظــام املشــار إليــه لقــاء مــا أســند إليــه‪2 .‬ـ منعــه‬\n      ‫مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة ســجنه وفق ـ ًا‬\n      ‫للفقــرة (األولــى) مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه‪3 .‬ـ عقوبــة‬\n      ‫تعزيريــة بحقــه لقــاء تســتره علــى مصــدر مــا ضبــط‪4 .‬ـ بالعقوبــة الــواردة‬\n      ‫يف املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف بحدهــا األعلــى بحقــه‬\n\n\n‫‪109‬‬\n\f‫خلطــورة مــا أقــدم عليــه ولتماديــه يف غيــه اســتناد ًا لبرقيــة صاحــب الســمو‬\n‫امللكــي اميــر منطقــة الريــاض بالنيابــة رقــم (‪/16745‬س) وتاريــخ‬\n‫‪1430/8/17‬هــ‪ .‬وبــاهلل التوفيــق وبســؤال املدعــى عليــه عــن دعــوى‬\n‫ا مــا ذكــره املدعــي العــام يف‬  ‫املدعــي العــام اجــاب املدعــى عليــه قائ ـ ً‬\n‫ا فقــد حــزت (‪ )14‬اربعــة عشــر حبــة‬    ‫دعــواه كلــه صحيــح جملــة وتفصيـ ً‬\n‫حتــوي عقــار الكلونازيبــام املهــدئ احملظــور و(‪ )17‬ســبعة عشــرة حبــة‬\n‫وأربعــة انصــاف احلبــة مــن حبــوب اإلمفيتامــن املنبــه احملظــور بقصــد‬\n‫التعاطــي وتعاطيــت احلبــوب احملظــورة وحاولــت ادخــال حبــوب محظــورة‬\n‫بتوقيــف مكافحــة املخــدرات بشــرق الريــاض وتســترت علــى مصــدر مــا‬\n‫ضبــط وليــس علــي ســوابق هكــذا اجــاب وباالطــاع علــى اوراق املعاملــة‬\n‫وجــدت تقريــر كيميائــي شــرعي رقــم (‪ )........‬لعــام ‪1434‬ه ـ واملتضمــن‬\n‫إيجابيــة العينــة املرســلة ملــادة كلونازيبــام وهــو مــن املــواد املهدئــة‬\n‫كمــا جــرى االطــاع علــى تقريــر كيميائــي شــرعي رقــم (‪ )........‬لعــام‬\n‫‪1434‬ه ـ واملتضمــن ايجابيــة العينــة املرســلة ملــادة اإلمفيتامــن وهــو مــن‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واالجابــة وحيــث اقــر‬   ‫املــواد املنبهــة فبنـ ً‬\n‫املدعــى عليــه بصحــة دعــوى املدعــي العــام وحيــث ان مــا أقــدم عليــه‬\n‫ـاء علــى املــادة ‪ 41‬و ‪ 56‬مــن نظــام‬‫فعــل محــرم يســتحق عليــه اجلــزاء وبنـ ً‬\n‫ـاء علــى املــادة ‪ 29‬مــن نظــام الســجن والتوقيــف‬  ‫مكافحــة املخــدرات وبنـ ً‬\n‫لهــذا كلــه فقــد ثبــت لــدي ادانــة املدعــى عليــه بحيــازة (‪ )14‬اربعــة عشــر‬\n‫حبــة حتــوي عقــار الكلونازيبــام املهــدئ احملظــور و(‪ )17‬ســبع عشــرة‬\n‫حبــة وأربعــة انصــاف احلبــة مــن حبــوب اإلمفيتامــن املنبــه احملظــور‬\n‫بقصــد التعاطــي وتعاطيــه احلبــوب احملظــورة ومحاولتــه إدخــال حبــوب‬\n‫محظــورة بتوقيــف مكافحــة املخــدرات بشــرق الريــاض وتســتره علــى‬\n\n\n                                                                                          ‫‪110‬‬\n\f      ‫مصــدر مــا ضبــط وقــررت تعزيــره لقــاء حيــازة احلبــوب احملظــورة بقصــد‬\n      ‫التعاطــي املذكــورة بســجنه ملــدة ســتة اشــهر وتعزيــره لقــاء محاولتــه‬\n      ‫ادخــال احلبــوب احملظــورة بســجنه ملــدة ســتة أشــهر ليصبــح مجمــوع‬\n      ‫ســجنه لقــاء حيــازة احلبــوب احملظــورة بقصــد التعاطــي ومحاولــة ادخــال‬\n      ‫احلبــوب احملظــورة مــدة ســنة مــع احتســاب مــدة ايقافــه الســابقة يف هــذه‬\n      ‫القضيــة وجلــده لقــاء تعاطيــه احلبــوب احملظــورة ســبعني جلــده ومنعــه مــن‬\n      ‫الســفر الــى خــارج اململكــة ملــدة ســنتني تبــدا بعــد نهايــة تنفيــذ عقوبــة‬\n      ‫ســجنه املذكــورة وأمــا مــا يتعلــق بتعزيــره لقــاء التســتر فهــو داخــل يف‬\n      ‫العقوبــة التعزيريــة املذكــورة ومبــا ذكــر حكمــت وبعــرض احلكــم‬\n      ‫علــى املدعــي العــام واملدعــى عليــه قــرر املدعــى عليــه القناعــة باحلكــم‬\n      ‫وامــا املدعــي العــام فقــرر عــدم القناعــة باحلكــم وطلــب التمييــز فأجبتــه‬\n      ‫ا إننــي أكتفــي بالئحــة الدعــوى‬      ‫لطلبــه ثــم قــرر املدعــي العــام قائ ـ ً‬\n      ‫العامــة فهــي الالئحــة االعتراضيــة هكــذا قــرر ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/04/20‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ،،‬ففقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزئيــة بالريــاض برقــم‬\n      ‫‪ 34894077‬وتاريــخ ‪1434/05/01‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ....../‬املســجل برقــم ‪34193641‬‬\n      ‫وتاريــخ ‪1434/04/21‬ه ـ اخلــاص بدعــوى املدعــي العــام ضد‪/‬املدعــى‬\n      ‫عليــه التهامــه بقضيــة مخــدرات علــى النحــو املوضح بالقرار املتضمن‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه ‪ .‬وبدراســة القــرار وصــورة‬\n      ‫ضبطــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق‬\n             ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n‫‪111‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":106,"source_page_end":111,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"482b5b475efc892a0f297a4c0a711be53a797e8c4b45b422491ee7b1db42bc54","normalized_text_hash":"70ab14d9db7820f66e71baacd7026156b084acb609361189b2c81cc249fa77d8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p106-34193641"},{"id":"cb457d18-29ad-5231-93eb-0b2a685d4819","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلشيش املخدر بقصد التعاطي -إقرار -التعزير بالسجن -منع من السفر.","document_number":"34274417","case_number":"34171923","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية السادسة برقم 34283832يف 1434/7/30ه جاء","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/18","year":"1434","subject":"مخدرات -حيازة احلشيش املخدر بقصد التعاطي -إقرار -التعزير بالسجن -منع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34274417 :‬تاريخه‪1434/7/18 :‬هـ‬\n                   ‫رقم الدعوى‪34171923 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34306345‬تاريخه‪1434/08/25 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة احلشــيش املخــدر بقصــد التعاطــي ‪ -‬إقــرار ‪ -‬التعزير‬\n                                              ‫بالســجن ‪ -‬منــع من الســفر‪.‬‬\n\n\n\n\n                 ‫املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد املدعــى عليــه بحيــازة احلشــيش املخــدر بقصــد‬\n‫التعاطــي‪ ،‬طلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه‬\n‫بالســجن بحــده األعلــى لتعــدد ســوابقه وفق ـ ًا للفقــرة األولــى مــن املــادة‬\n‫(‪)56‬مــن نظــام مكافحــة املخــدرات واملؤاثــرات العقليــة‪ ،‬مت القبــض‬\n‫علــى املدعــى عليــه بعــد ضبطــه مــن إحــدى الدوريــات حيــث مت االشــتباه‬\n‫بــه وبتفتيشــه عثــر معــه بجيبــه علــى قطعــة مــن احلشــيش املخــدر‪ ،‬إقــرار‬\n‫املدعــى عليــه بالدعــوى‪ ،‬تعزيــر املدعــى عليــه بالســجن واملنــع مــن‬\n                   ‫الســفر‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                     ‫‪112‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالطائــف برقــم ‪ 34171923‬وتاريــخ ‪1434/04/15‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34917432‬وتاريــخ ‪ 1434/04/15‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق ‪1434/07/18‬ه ـ افتتحــت اجللســة الســاعة ‪30‬‬\n      ‫‪ 09 :‬وفيهــا حضــر املدعــي العــام ‪ ...........‬بالتعميــد رقــم ‪ 1607‬يف‬\n      ‫‪1433/10/18‬ه ـ وادعــى علــى احلاضــر باملجلــس الشــرعي ‪...........‬‬\n      ‫ا أنــه بتاريــخ‬\n                     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ............‬قائـ ً‬\n      ‫‪1434/3/17‬ه ـ ضبطــت دوريــة مكافحــة املخــدرات بطريــق الريــاض‬\n      ‫الســيارة نــوع ‪ ......‬رقــم لوحتهــا (‪ )...........‬قيــادة ‪ - ........... :‬لــم يتهــم‬\n      ‫لعــدم األدلــة ‪ -‬ويرافقــه املدعــى عليــه وبتفتيــش املدعــى عليــه عثــر بجيــب‬\n      ‫ثوبــه علــى قطعــة تــزن (‪ )0،2‬عشــري جــرام ثبــت بالتقريــر الكيميائــي‬\n      ‫الشــرعي رقــم (‪ )...........‬يف ‪1434/3/23‬ه ـ ايجابيتهــا للحشــيش املخــدر‬\n      ‫املــدرج باجلــدول (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات وباســتجواب‬\n      ‫املدعــى عليــه أقــر بأنــه قبــض عليــه وبتفتيشــه عثــر بجيــب ثوبــه علــى‬\n      ‫قطعــة تــزن (‪ )0.2‬عشــري جــرام مــن احلشــيش وهــي لــه بقصــد التعاطــي‬\n      ‫وقــد أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بحيــازة قطعــة‬\n      ‫تــزن (‪ )0.2‬عشــري جــرام مــن احلشــيش املخــدر بقصــد التعاطــي واملجــرم‬\n      ‫نظام ـ ًا وفق ـ ًا للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬يف ‪1426/7/8‬ه ـ‬\n      ‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬إقــراره املنــوه عنــه املــدون لفــة (‪)1‬‬\n\n‫‪113‬‬\n\f‫صفحــة (‪ -2 . )11‬محضــر القبــض والتفتيــش املنــوه عنــه املــدون لفــة (‪)1‬‬\n‫صفحــة (‪ -3 . )11‬التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة‬\n‫(‪ . )14‬وبالبحــث عــن ســوابقه عثــر عليــه ثــاث ســوابق مســجلة ‪ :‬قتــل‬\n‫ومضاربــة وشــرب املســكرات وحيــث إن مــا أقــدم عليــه املدعــى عليــه‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم شــرع ًا ومجــرم نظامـ ًا‬\n‫وفق ـ ًا ملــا أشــير إليــه لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n‫باآلتــي‪ -1 :‬الســجن بحــده األعلــى وفقـ ًا للفقــرة األولى مــن املادة الواحدة‬\n‫واألربعــن ووفق ـ ًا للتعميــم رقــم (‪ )593958/5/1‬يف ‪1429/8/23‬ه ـ‬\n‫لتعــدد ســوابقه وعــدم إرتداعــه ‪ -2 .‬منعــه مــن الســفر خــارج اململكــة‬\n‫بعــد تنفيــذ العقوبــة وفقـ ًا للفقــرة األولــى مــن املــادة السادســة واخلمســن‬\n‫هــذه دعــواي ‪ .‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب ما‬\n‫ذكــره املدعــي العــام صحيــح والســوابق التــي علــي صحيحــة وباالطــاع‬\n‫علــى التقريــر الكيميائــي الشــرعي رقــم ‪ ...........‬يف ‪1434/3/23‬ه ـ‬\n‫اثبــت احتــواء العينــة علــى مــادة احلشــيش املخــدر فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة املتضمنــة املصادقــة علــى الدعــوى ولوجــود ثــاث‬\n‫ســوابق مصــادق عليهــا إحداهــا قتــل وايجابيــة التقريــر الكيميائــي‬\n‫فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة قطعــة مــن احلشــيش تــزن‬\n‫‪ 0.2‬جــم وحكمــت عليــه بســجنه ملــدة ســنة وســتة أشــهر ومنعــه مــن‬\n‫الســفر خــارج اململكــة ملــدة ســنتني تبــدأ بعــد انتهــاء العقوبــة بنــاء علــى‬\n‫املــادة ‪ 41‬واملــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات وبعــرض احلكــم‬\n‫علــى املدعــى عليــه اعتــرض علــى احلكــم بــدون الئحــة واعتــرض املدعــي‬\n‫العــام بالئحــة اعتراضيــة فجــرى تســليمه نســخة احلكــم وأفهمتــه بــأن‬\n‫مــدة تقــدمي الالئحــة ثالثــن يومـ ًا بنــاء علــى املــادة ‪ 194‬و ‪ 195‬مــن نظــام‬\n\n\n                                                                                       ‫‪114‬‬\n\f      ‫االجــراءات اجلزائيــة وبــاهلل التوفيــق حــرر يف ‪1434/7/18‬ه ـ الســاعة‬\n                                                                    ‫العاشــرة صباح ـ ًا ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالطائــف برقــم ‪ 34171923‬وتاريــخ ‪ 1434/04/15‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34917432‬وتاريــخ ‪ 1434/04/15‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافــق ‪1434/08/13‬ه ـ افتتحــت اجللســة الســاعة الواحــدة‬\n      ‫حيــث عــادت املعاملــة مــن محكمــة اإلســتئناف مالحــظ عليهــا بقــرار‬\n      ‫الدائــرة اجلزائيــة السادســة برقــم ‪ 34283832‬يف ‪1434/7/30‬ه ـ جــاء‬\n      ‫فيــه وبدراســة القــرار وصــورة ضبطــه والئحتــه اإلعتراضيــة تقــرر‬\n      ‫إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن فضيلتــه أثبــت حيــازة املدعــى‬\n      ‫عليــه للحشــيش املخــدر ولــم يذكــر القصــد وجوابــا علــى ماذكــره‬\n      ‫أصحــاب الفضيلــة فقــد كان ذلــك ســقطا مــن الكاتــب وصوابــه‬\n      ‫أن احليــازة بقصــد التعاطــي كمــا هــو مذكــور يف الدعــوى واإلجابــة‬\n      ‫واحلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/13‬ه ـ الســاعة الواحــدة والربــع ‪.‬‬\n      ‫احلمد هلل وحده وبعد ففي يوم األحد املوافق‪ 1434/09/13‬هـ افتتحت‬\n      ‫اجللســة الســاعة الثانيــة حيــث عــادت املعاملــة مــن محكمــة اإلســتئناف‬\n      ‫مصادقــا عليهــا بقــرار الدائــرة اجلزائيــة السادســة برقــم ‪ 34306345‬يف‬\n      ‫‪1434/8/25‬ه ـ ولــذا جــرى إثباتــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1434/09/13‬ه ـ‬\n                                                              ‫الســاعة الثانيــة والربــع‪.‬‬\n                 ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n\n\n‫‪115‬‬\n\f‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n‫مبكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه‬\n‫احملكمــة بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بالطائــف‬\n‫رقــم (‪ )341579985‬وتاريــخ (‪1434/8/15‬هــ) املرفــق بهــا القــرار‬\n‫رقــم (‪ )34272417‬وتاريــخ (‪1434/7/18‬هــ) الصــادر مــن فضيلــة‬\n‫الشــيخ‪ .........../‬القاضــي باحملكمــة اجلزائيــة بالطائف‪،‬املتضمــن‬\n‫دعــوى املدعــي العــام ضــد‪ .........../‬ســعودي اجلنســية ‪ ،‬املتهــم يف‬\n‫حشــيش مخــدر‪ ،‬احملكــوم فيــه مبــادون باطنــه ‪ ،‬واملالحــظ عليــه‬\n‫بقــرار محكمة االســتئناف رقم‪34283832‬وتاريخ‪1434/7/30‬هـ‪،‬وب‬\n‫دراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم بعــد اجلــواب األخيــر‪ ،‬واهلل املوفق‪،‬وصلــى اهلل علــى نبينــا‬\n                                        ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                ‫‪116‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":112,"source_page_end":116,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"214ea13fd897ff9b095c7ee2ca76f5497815ad98504df4649904588d57a40400","normalized_text_hash":"fe4dcd9438d7c47a4915208bf213268ae0a7ea658fc489f2e7455d51fdd42e44","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p112-34274417"},{"id":"6a443d27-97f8-5b60-8153-9cf1dbc0dcf5","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة كوكاين بقصد الترويج والشروع يف بيعه بقصد االجتار -إقرار -إدانة -املتهم وافد -نزول عن احلد األدنى للعقوبة -تعزير بالسجن واجللد والغرامة واالبعاد من الباد .","document_number":"34268577","case_number":"34172801","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/15","year":"1434","subject":"مخدرات -حيازة كوكاين بقصد الترويج والشروع يف بيعه بقصد االجتار -إقرار -إدانة -املتهم وافد -نزول عن احلد األدنى للعقوبة -تعزير بالسجن واجللد والغرامة واالبعاد من الباد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34268577:‬تاريخه‪1434/07/15 :‬هـ‬\n                          ‫رقم الدعوى‪34172801:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34354992‬تاريخه‪1434/11/09:‬هـ‬\n\n\n       ‫مخــدرات‪ -‬حيــازة كوكايــن بقصــد الترويــج والشــروع يف بيعــه بقصد‬\n       ‫االجتــار‪ -‬إقــرار‪ -‬إدانــة‪ -‬املتهــم وافــد ‪-‬نــزول عــن احلــد األدنــى للعقوبــة‬\n                     ‫‪ -‬تعزيــر بالســجن واجللــد والغرامــة واالبعــاد مــن البــاد ‪.‬‬\n\n\n\n\n       ‫املــواد (‪ )38‬و(‪ )53‬و(‪ )56‬و (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                       ‫العقلية‪.‬‬\n\n\n\n       ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n       ‫بحيــازة الكوكايــن املخــدر بقصــد الترويــج وشــروعه يف بيعــه بقصــد‬\n       ‫االجتــار‪ ،‬واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة واإلبعــاد عــن‬\n       ‫البــاد طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ -‬مت االتفاق‬\n       ‫معه على شراء كمية من مادة الكراك املخدر وبعد مقابلته للمصدر‬\n       ‫ا مــن يــده اليســرى تبــن أن بــه مــادة‬\n                                                ‫تقدمــت الفرقــة نحــوه فرمــى منديـ ً‬\n       ‫بيضــاء اللــون هــي الكميــة املتفــق عليهــا‪ -‬أثبــت التقريــر الكيميائــي‬\n       ‫الشــرعي إيجابيــة العينــة املرســلة للكوكايــن املخــدر‪ -‬أنكــر أمــام‬\n       ‫احملكمــة مــا أســنده إليــه املدعــي العــام ثــم أقــر بذلــك بعــد مواجهتــه‬\n       ‫بشــهود محضــر القبــض‪ -‬قضــت احملكمــة بإدانــة املدعــى عليــه بجميــع‬\n\n‫‪117‬‬\n\f‫مــا نســب إليــه وقــررت ســجنه ملــدة ســنتني ونصــف الســنة وجلــده مائتــي‬\n‫جلــدة علــى أربــع دفعــات وتغرميــه مبلــغ ألفــي ريــال وإبعــاده عــن البــاد‬\n‫بعــد انتهــاء محكوميتــه‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي‬\n       ‫العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وبعــد فــدي أنــا‬\n‫‪ ........‬القاضــي باحملكمــة اجلزائيــة مبحافظــة جــدة والقائــم بعمــل‬\n‫القاضــي باحملكمــة فضيلــة الشــيخ ‪ ........‬مبوجــب خطــاب التكليــف‬\n‫الصــادر مــن فضيلــة مســاعد رئيــس احملكمــة برقــم ‪34965789‬وتاريــخ‬\n‫‪1434/04/20‬ه ـ افتتحــت اجللســة يف متــام الســاعة العاشــرة صباحـ ًا مــن‬\n‫ـاء علــى املعاملــة احملالــة‬\n                            ‫هــذا اليــوم الثالثــاء املوافــق ‪1434/04/23‬ه ـ بنـ ً‬\n‫إلينــا بشــرح فضيلــة الرئيــس برقم ‪ 34172801‬وتاريــخ ‪1434/04/15‬هـ‬\n‫واملقيــدة برقــم ‪ 34911643‬وتاريــخ ‪1434/04/14‬ه ـ وفيهــا حضــر‬\n‫املدعــي العــام ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n‫عضــو هيئــة التحقيــق واالدعــاء العــام مبحافظــة جــدة املعمــد مــن هيئــة‬\n‫التحقيــق واالدعــاء العــام مبوجــب خطــاب التعميــد رقم (ه ـ م‪)3200/6/‬‬\n‫وتاريــخ ‪1434/01/13‬ه ـ وقــدم الئحــة دعــواه ضد احلاضــر معه باملجلس‬\n‫الشــرعي ‪ )33( ،........‬عامـ ًا ‪ ،‬تشــادي اجلنســية مبوجــب البطاقــة البديلة‬\n‫رقــم‪ ، ........‬الصــادرة مــن مكافحــة املخــدرات مبحافظــة جــدة بتاريــخ‬\n‫‪1434/1/29‬ه ـ ‪ ،‬موقــوف بالســجن العــام مبحافظــة ج ـ ــدة مبوجــب‬\n‫أمــر متديــد التوقيــف رق ــم(هـ م‪ )7862/5/2‬وتاريـ ــخ ‪1434/2/3‬ه ـ‬\n‫اســتنادا للقــرار الــوزاري رقــم (‪ )1900‬املبنــي علــى املــادة (‪ )112‬مــن‬\n\n                                                                                      ‫‪118‬‬\n\f      ‫نظــام اإلجــراءات اجلزائيــة ‪ ،‬املقبــوض عليــه بتاريــخ ‪1434/1/29‬ه ـ‬\n      ‫فإنــه بتاريــخ ‪1434/1/29‬ه ـ قبــض عليــه مــن قبــل فرقــة مكافحــة‬\n      ‫املخــدرات بجــدة إثــر االتفــاق معــه علــى شــراء كميــة مــن مــادة الكراك‬\n      ‫املخــدر مببلــغ (‪ )2800‬ألفــن وثمامنائــة ريــال ‪ ،‬وحضــوره ومعــه شــخص‬\n      ‫ا مــن يــده‬\n                 ‫ومقابلتهمــا للمصــدر ‪ ،‬وعنــد تقــدم الفرقــة نحــوه رمــى منديـ ً‬\n      ‫اليســرى تبــن أن بــه مــادة بيضــاء اللــون تــزن (‪ )4‬أربعــة جرامــات وهــي‬\n      ‫الكميــة املتفــق عليهــا ‪ ،‬ومتكــن الشــخص اآلخــر مــن الهــرب وقــد أثبــت‬\n      ‫التقريــر الكيمي ـ ـ ــائي الشــرعي رق ـ ـ ــم (‪/379‬ك ش م) لعـ ـ ــام ‪1434‬ه ـ‬\n      ‫احتــواء عين ــة مــا مت ضبطــه علــى مــادة الكوكايــن املخــدر املدرجــة‬\n      ‫باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة وانتهــى التحقيــق إلــى اتهــام املدعــى عليــه بحيــازة (‪ )4‬أربــع‬\n      ‫جرامــات مــن مــادة الكوكايــن املخــدر بقصــد الترويــج والشــروع يف‬\n      ‫بيعهــا بقصــد االجتــار‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪ -1 -:‬مــا ورد يف‬\n      ‫ا املرفــق لفة‬‫شــهادة الشــهود الــواردة مبحضــر الضبــط املنــوه عنــه تفصيـ ً‬\n      ‫رقــم (‪ -2 .)1‬مــا ورد بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق‬\n      ‫لفــة رقــم (‪ )23‬وباالطــاع علــى صحيفــة احلالــة اجلنائيــة عثــر لــه علــى‬\n      ‫ســابقتي ترويــج املخــدرات وحيــث أن مــا أقــدم عليــه املدعــى عليــه وهــو‬\n      ‫بكامــل أهليتــه املعتبــرة شــرع ًا مــن األفعــال احملرمــة شــرع ًا واملجرمــة‬\n      ‫نظام ـ ًا طبق ـ ًا للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة الصــادر باملرســوم امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬هــ‪،‬‬\n      ‫لــذا اطلب‪/‬إثبــات مــا أســند إليــه واحلكــم عليــه بالعقوبــات األصليــة‬\n      ‫والتكميليــة التاليــة‪ )1 :‬بالســجن واجللــد والغرامــة مــع تشــديد العقوبــة‬\n      ‫عليــه اســتناد ًا للفقــرة (‪ )1‬والفقــرة (‪ )2‬احلالــة (ج) مــن املــادة (‪ )38‬مــن‬\n\n\n‫‪119‬‬\n\f‫نظــام مكافحــة املخــدرات املشــار إليــه‪ )3 .‬إبعــاده خلــارج اململكــة بعــد‬\n‫االنتهــاء مــن تنفيــذ عقوبتــه وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن نظــام‬\n‫مكافحــة املخــدرات املشــار إليــه هكــذا ادعــى وبتــاوة دعــوى املدعــي‬\n‫ا مــا ذكــره املدعــي‬  ‫العــام علــى املدعــى عليــه أجــاب يحســن العربيــة قائـ ً‬\n‫العــام مــن اتهامــي بحيــازة (‪ )4‬أربــع جرامــات مــن مــادة الكوكايــن‬\n‫املخــدر بقصــد الترويــج والشــروع يف بيعهــا بقصــد االجتــار فهــذا كلــه‬\n‫ا والصحيــح ليــس لــي عالقــة مبــا ضبــط‬        ‫غيــر صحيــح جملــة وتفصي ـ ً‬\n‫بجانبــي وال أقــوم بترويــج املخــدرات وبســؤال املدعــي العــام عــن البينــة‬\n‫ـدي بينــة وأطلــب اإلمهــال إلحضارهــا يف اجللســة‬      ‫أجــاب بقولــه نعــم لـ ّ‬\n‫القادمــة فأجبتــه لطلبــه احلمــد هلل وحــده والصــاة والســام علــى مــن‬\n‫ال نبــي بعــده وبعــد فلــدي أنــا القاضــي باحملكمــة اجلزائيــة مبحافظــة‬\n‫جــدة افتتحــت اجللســة وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى‬\n‫عليــه وبســؤال املدعــي العــام عمــا رفعــت اجللســة الســابقة ألجلــه أحضــر‬\n‫كل مــن‪ /1 :‬جنــدي أول ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ /2 ........‬اجلنــدي ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ........‬ولــدى استشــهادهم شــهد كل واحــد منهــا بقولــه أشــهد هلل‬\n‫ـاء علــي إخباريــة مــن متعــاون مفادهــا مت االتفــاق مــع املدعــى‬\n                                                                   ‫تعالــى أنــه بنـ ً‬\n‫عليــه علــى شــراء كميــة مــن مــادة الكــراك املخــدر مببلــغ (‪)2800‬‬\n‫ألفــن وثمامنائــة ريــال ‪ ،‬وحضــوره ومعــه شــخص ومقابلتهمــا للمصــدر‬\n‫ا مــن يــده اليســرى تبــن أن‬      ‫‪ ،‬وعنــد تقــدم الفرقــة نحــوه رمــى مندي ـ ً‬\n‫بــه مــادة بيضــاء اللــون تــزن (‪ )4‬أربعــة جرامــات وهــي الكميــة املتفــق‬\n‫عليهــا ‪ ،‬ومتكــن الشــخص اآلخــر مــن الهــرب هــذا مــا لدينــا ونشــهد بــه‬\n‫أمــام اهلل ســبحانه وتعالــى ثــم رفعــت اجللســة بعــد ذلــك إلحضــار املدعــى‬\n\n\n                                                                                         ‫‪120‬‬\n\f      ‫عليــه وعــرض الشــهادة عليــه ويف جلســة أخــرى حضــر املدعــي العــام‬\n      ‫وأحضــر املدعــى عليــه وبعــرض شــهادة الشــهود علــى املدعــى عليــه‬\n      ‫ا وأنــا‬  ‫أجــاب جميــع مــا ورد بشــهادة الشــهود صحيــح جملــة وتفصي ـ ً‬\n      ‫ال‬‫نــادم علــى هــذا الفعــل وتائــب إلــى اهلل تعالــى ولــن أعــود ملثلــه مســتقب ً‬\n      ‫هــذا وقــد جــرى الرجــوع علــى أوراق املعاملــة ومنهــا التقريــر الكيميائــي‬\n      ‫الشــرعي املنــوه عنــه املرفــق لفــة رقــم (‪ )23‬املتضمــن احتــواء عين ــة مــا‬\n      ‫مت ضبطــه علــى مــادة الكوكايــن املخــدر املدرجــة باجلــدول رقــم (‪)1‬‬\n      ‫فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة كمــا‬\n      ‫جــرى االطــاع علــى مــا ورد يف شــهادة الشــهود الــواردة مبحضــر الضبــط‬\n      ‫ا املرفــق لفــة رقــم (‪ )1‬املتضمنــة مت القبــض عليــه مــن‬    ‫املنــوه عنــه تفصيـ ً‬\n      ‫قبــل فرقــة مكافحــة املخــدرات بجــدة إثــر االتفــاق معــه علــى شــراء‬\n      ‫كميــة مــن مــادة الكــراك املخــدر مببلــغ (‪ )2800‬ألفــن وثمامنائــة ريــال‬\n      ‫‪ ،‬وحضــوره ومعــه شــخص ومقابلتهمــا للمصــدر ‪ ،‬وعنــد تقــدم الفرقــة‬\n      ‫ا مــن يــده اليســرى تبــن أن بــه مــادة بيضــاء اللــون تــزن‬ ‫نحــوه رمــى منديـ ً‬\n      ‫(‪ )4‬أربعــة جرامــات وهــي الكميــة املتفــق عليهــا ‪ ،‬ومتكــن الشــخص‬\n      ‫اآلخــر مــن الهــرب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــر ًا‬\n      ‫إلــى أن املدعــى عليــه اعتــرف مبــا نســبه إليــه املدعــي العــام ونظــر ًا‬\n      ‫إلــى مــا جــاء يف أوراق املعاملــة وبعــد االطــاع علــى نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة وأن املدعــى عليــه األول ينطبــق بحقــه‬\n      ‫املــواد (‪ )56-53-38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫‪ ،‬وباالطــاع علــى صحيفــة ســوابق املدعــى عليــه عثــر لــه علــى ســابقتي‬\n      ‫ترويــج املخــدرات وبعــرض الســوابق عليــه أجــاب بقولــه صحيــح علـ ّـي‬\n      ‫هــذه الســوابق وقــد أخــذت جزاءهــا وأنــا تائــب منهــا فلمــا ســبق ولقلــة‬\n\n\n‫‪121‬‬\n\f‫الكميــة التــي قــام املدعــى عليــه بترويجهــا وكونــه أجنبــي وال فائــدة‬\n‫مــن طــول بقائــه يف الســجن وملقتضــى املــادة (‪ )60‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة التــي أجــازت النــزول عــن احلــد األدنــى يف‬\n‫العقوبــة املنصــوص عليــه يف املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات‬\n‫ـدي إدانــة املدعــى‬‫واملؤثــرات العقليــة فقــد قــررت مــا يلــي‪ /‬أوالً‪ :‬ثبــت لـ ّ‬\n‫بحيــازة (‪ )4‬أربــع جرامــات مــن مــادة الكوكايــن املخــدر بقصــد‬\n‫الترويــج والشــروع يف بيعهــا بقصــد االجتــار ثاني ـاً‪ :‬حكمــت بســجنه‬\n‫ملــدة ســنتني ونصــف الســنة يحتســب منهــا املــدة التــي قضاهــا يف الســجن‬\n‫بســبب هــذه القضيــة وجلــده مائتــي جلــدة مفرقــة علــى أربــع دفعــات كل‬\n‫دفعــة خمســن جلــدة بــن الدفعــة واألخــرى مــدة ال تقــل عــن عشــرة أيــام‬\n‫وتغرميــه مبلــغ وقــدره (‪ )2000‬ألفــن ريــال اســتناد ًا علــى املــواد (‪)60-38‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ثالث ـاً‪ :‬إبعــاده عــن‬\n‫البــاد بعــد انتهــاء محكوميتــه وعــدم الســماح لــه بدخولهــا إال فيمــا‬\n‫عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة اســتناد ًا علــى املــادة (‪)2/56‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة هــذا مــا ظهــر لــي وبــه‬\n‫حكمــت ألجــل احلــق العــام وجــرى نصــح املدعــى عليــه مبــا يناســب املقــام‬\n‫وبإعــان احلكــم علــى املدعــى عليــه قــرر قناعتــه بــه وأبدى املدعــي العام‬\n‫اعتراضــه عليــه وطلــب رفعــه الــى محكمــة االســتئناف واســتعد بتقــدمي‬\n‫الئحــة اعتراضيــة فأفهــم مبراجعتنــا يــوم االربعــاء ‪1434/07/19‬ه ـ‬\n‫الســتالم نســخة احلكــم وتقــدمي اعتراضــه عليــه خــال ثالثــون يومـ ًا مــن‬\n‫تاريــخ االســتالم وإن لــم يتقــدم باعتراضــه خاللهــا فيســقط حقــه يف‬\n‫االعتــراض وأقفلــت اجللســة يف متــام الســاعة العاشــرة والنصــف صباح ـ ًا‬\n‫وعلــى مــا تقــدم حصــل التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n                                                                                       ‫‪122‬‬\n\f                                     ‫وصحبــه وســلم حــرر يف ‪1434/07/15‬ه ـ ـ ‪.‬‬\n      ‫احلمــدهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪-:‬‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف مبكــة‬\n      ‫املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة‬\n      ‫بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بجــدة رقــم (‪)34911643‬‬\n      ‫وتاريــخ ‪ 1434/10/26‬ه ـ املرفــق بهــا القــرار رقــم (‪ )34268577‬وتاريــخ‬\n      ‫‪ 1434/7/15‬ه ـ الصــادر مــن فضيلــة القاضــي ‪ ........‬باحملكمة اجلزائية‬\n      ‫بجــدة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪ ...........‬تشــادي اجلنســية‪،‬‬\n      ‫املتهــم يف مخــدرات احملكــوم فيــه مبــادون باطنــه‪ ،‬وبدراســة القــرار‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تققــرت املوافقــة علــى احلكــم ‪،‬‬\n      ‫واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪123‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":117,"source_page_end":123,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"105b8d3e22ff7716839f4f1466c349287ece383e105186db7b8375c384753774","normalized_text_hash":"a16a9951179bfd2be87a1c29f572c4b7d140332a274c8dcd2a6c4ed17970de8e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p117-34268577"},{"id":"2c75a1e5-ee96-5fdc-8fd8-f6c3e4609995","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد التعاطي والترويج -قات -وجود سابقة -التعزير بالسجن واجللد والغرامة واملصادرة وإسقاط شريحة","document_number":"34193905","case_number":"34177079","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/21","year":"1434","subject":"مخدرات -حيازة بقصد التعاطي والترويج -قات -وجود سابقة -التعزير بالسجن واجللد والغرامة واملصادرة وإسقاط شريحة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34193905 :‬تاريخه‪1434/4/21 :‬هـ‬\n                    ‫رقم القضية‪34177079 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34231343‬تاريخه‪1434/6/5:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة بقصــد التعاطــي والترويــج ‪ -‬قــات ‪ -‬وجــود ســابقة‬\n ‫‪ -‬التعزيــر بالســجن واجللــد والغرامــة واملصــادرة وإســقاط شــريحة‬\n                                                                  ‫جــوال‪.‬‬\n\n\n\n ‫املادتــن الثالثــة والرابعــة مــن قــرار وزيــر الداخليــة رقــم ‪ 2057‬مــن‬\n                                                          ‫‪1404/5/26‬ه ـ ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة نبــات القــات احملظــور‬\n ‫بقصــد الترويــج والتعاطــي وتعاطيــه وبيعــه وطلــب املدعــي العــام إثبــات‬\n ‫مــا اســند إليــه واحلكــم عليــه بعقوبــة الســجن والغرامــة ومصــادرة‬\n ‫الهاتــف اجلــوال وإســقاط شــريحته املســتخدم يف اجلرميــة ‪،‬حيــث إنــه‬\n ‫مت القبــض علــى املدعــى عليــه بعــد إخباريــة مفادهــا إن املدعــى عليــه‬\n ‫يقــوم بترويــج القــات فتــم التنســيق بــن املصــدر واملــروج وتقابــا يف‬\n ‫املوقــع احملــدد وقبــض علــى املــروج بعــد عمليــة االســتالم والتســليم ‪،‬أقـ ّـر‬\n ‫املدعــى عليــه بالدعــوى‪ ،‬وجــود ســابقة علــى املدعــى عليــه‪ ،‬بنــاء علــى‬\n ‫مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد‬\n ‫والغرامــة ومصــادرة الهاتــف اجلــوال املســتخدم يف اجلرميــة وإســقاط‬\n\n                                                                                        ‫‪124‬‬\n\f                         ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n                                                                ‫شــريحته ُ‬\n\n\n\n      ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد لدي أنا ‪.....‬‬\n      ‫القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n      ‫فضيلة رئيس احملكمة اجلزائية يف محافظة ‪ ............‬برقم ‪34177079‬‬\n      ‫وتاريــخ ‪1434/04/17‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34945721‬وتاريــخ‬\n      ‫‪1434/04/17‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/04/21‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 : 45‬وفيهــا قــدم املدعــي العــام ‪ ......‬الئحــة دعــوى‬\n      ‫ا فيهــا‬ ‫عامــة ضــد ‪ ........‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ .....‬قائـ ً‬\n      ‫باالطــاع علــى محضــر االنتقــال و القبــض والتفتيــش املعــد مــن قبــل‬\n      ‫رجــال الضبــط اجلنائــي بشــعبة مكافحــة املخــدرات بالدمــام تبني أنه يف‬\n      ‫يــوم األحــد املوافــق ‪1434/2/17‬ه ـ ورد بــاغ مــن أحــد املصــادر الســرية‬\n      ‫عــن شــخص يدعــى (‪ ).....‬يقــوم بترويــج القــات املخــدر ويســتخدم هاتفــه‬\n      ‫اجلــوال رقــم (‪ )....‬فتــم متكــن املصــدر مــن االتصال عليــه وطلب منه قات‬\n      ‫مببلــغ (‪ )700‬ســبعمائة ريــال فــرد املــروج أنهــا موجــودة وســيحضر إلــى‬\n      ‫شــقة املصــدر فتــم تزويــد املصــدر مببلــغ مرقــم وتكليــف أحــد أعضــاء‬\n      ‫الفــر قــه القابضــة مبرافقــة املصــدر وباقــي أعضــاء الفرقــة القابضــة‬\n      ‫كان تواجدهــم خــارج شــقة املصــدر للمراقبــة وبعــد نصــف ســاعة حضر‬\n      ‫شــخص يحمل معه كيس ودخل شــقه املصدر وبعد دقائق أعطى رجل‬\n      ‫األمــن املرافــق للمصــدر إشــارة االســتالم والتســليم ومت مداهمــة الشــقة‬\n      ‫والقبــض علــى املــروج والــذي اتضــح انــه املتهــم املذكــور وأن مــا قــام‬\n      ‫بترويجــه هــو حزمــة مــن نبــات القــات احملظــور بلــغ وزنــه (‪ )446‬أربعمائــة‬\n\n‫‪125‬‬\n\f‫وســتة وأربعــون جرامـ ًا وبتفتيــش الكيــس الــذي كان يحملــه عثــر علــى‬\n‫عــدة حــزم خضــراء اللــون بلــغ وزنهــا جميعــا (‪ )800‬ثمامنائــة جــرام وأفــاد‬\n‫للجهــة القابضــة أنــه يحتــاز باقــي الكميــة يف منزلــه وباالنتقــال ملنزلــه‬\n‫عثــر يف جهــاز التبريــد علــى عــدة حــزم خضــراء اللــون بلــغ وزنهــا جميعــا‬\n‫(‪ ()8916‬ثمانيــة آالف وتســعمائة وســتته عشــر جــرام وبتفتيشــه عثــر‬\n‫معــه علــى املبلــغ املرقــم كمــا عثــر معــه علــى جــوال يحمــل نفــس الرقــم‬\n‫الــذي مت عليــه التنســيق أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪906‬‬\n‫ك ش) وتاريــخ ‪1434/2/26‬ه ـ أن مــا مت ضبطــه للترويــج واحليازة بقصد‬\n‫االســتخدام إنهــا لنبــات القــات احملظــور واملــدرج باجلــدول األول رقــم (‪)4‬‬\n‫الفقــرة رقــم (‪ )5‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة مت‬\n‫إيقــاف املتهــم املذكــور بالســجن رهــن احملاكمــة لكــون جرميتــه مــن‬\n‫اجلرائــم الكبيــرة املوجبــة لإليقــاف وفقـ ًا للقــرار الــوزاري رقــم (‪)1900‬‬\n‫وتاريــخ ‪1428/7/9‬ه ـ وباســتجوابه اقــر ببيعــه مــا وزنــه (‪ )446‬أربعمائــة‬\n‫وســتة وأربعــون جرام ـ ًا مــن نبــات القــات احملظــور وبحيازتــه مــا وزنــه‬\n‫(‪ )800‬ثمامنائــة جــرام و(‪ ()8916‬ثمانيــة آالف وتســعمائة وســتة عشــر‬\n‫جــرام بقصــد التعاطــي وتعاطيــه لــه وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n‫ل ـ ‪ .... :‬باالتــي‪ -1‬ببيــع مــا وزنــه (‪ )446‬أربعمائــة وســتة وأربعــون جرامـ ًا‬\n‫مــن نبــات القــات احملظــور بقصــد االجتــار ‪ -2‬حيازتــه مــا وزنــه (‪)9716‬‬\n‫تســعة االف وســبعمائة وســتة عشــر جرام ـ ًا بقصــد التعاطــي وتعاطيــه‬\n‫لــه وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬اعترافــه مبــا نــوه عنــه املــدون‬\n‫مبحضــر اســتجوابه املرفــق علــى اللفــات رقــم (‪ -2)13‬محضــر القبــض‬\n‫والتفتيــش املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪)12‬املرفــق علــى‬\n‫اللفــة رقــم (‪ -3)1‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى‬\n\n\n                                                                                      ‫‪126‬‬\n\f                                                                          ‫اللفــة رقــم (‪.)19‬‬\n      ‫‪ -4‬ضبــط املبلــغ املرقــم والهاتــف النقــال املســتخدم يف عمليــة البيــع‬\n      ‫مــع املتهــم املذكــور دليــل علــى عمليــة البيــع وحيــث أن مــا أقــدم عليــه‬\n      ‫املذكــور وهــو بكامــل أهليتــه املعتبــرة محــرم شــرعا ومعاقــب عليــه‬\n      ‫شــرعا ونظامــا أطلــب مــا يلــي أوالً‪ :‬إثبــات مــا أســند إليــه وفق ـ ًا للقــرار‬\n      ‫رقــم (‪ )11‬يف ‪1374/02/01‬ه ـ واحلكــم عليــه بعقوبــة الســجن والغرامــة‬\n      ‫الــواردة بالفقــرة رقــم (‪ )3‬بالقــرار رقــم (‪ )11‬بتاريــخ ‪1374/02/01‬ه ـ‬\n      ‫واملعــدل بقــرار وزيــر الداخليــة رقــم (‪ )2057‬لعــام ‪1404‬ه ـ لقــاء بيعــه‬\n      ‫للقــات املخــدر واحملظــور وتعاطيــه لــه ثانيــا‪ :‬مصــادرة الهاتــف اجلــوال‬\n      ‫العائــد للمذكــور مــن نــوع يحمــل الرقــم (‪)........................‬الســتخدامه‬\n      ‫يف بيــع نبــات القــات احملظــورة وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n      ‫(‪ )53‬مــن النظــام ‪ ،‬مــع املطالبــة بإســقاط شــريحة الهاتــف النقــال‬\n      ‫وعــدم صرفهــا لنفــس املتهــم وفقــا لتعميــم ســمو وزيــر الداخليــة رقــم‬\n      ‫(‪ )9798‬وتاريــخ ‪1429/2/10-9‬ه ـ هــذه دعــواي وبســؤال املدعــى عليــه‬\n      ‫عــن الدعــوى أجــاب بقولــه مــا جــاء يف الدعــوى كلــه صحيــح ففــي‬\n      ‫تاريــخ ‪1434/2/17‬ه ـ ورد اتصــال علــى هاتفــي اجلــوال نــوع ‪ .....‬ورقــم‬\n      ‫جوالــي هــو (‪ )................‬وكان املتصــل يطلــب منــي أن أبيعــه نبــات‬\n      ‫القــات احملظــور مببلــغ ســبعمائة ريــال فوافقــت علــى ذلــك وأخبــرت‬\n      ‫املتصــل بأنــي ســوف أحضــر لــه يف شــقته ومعــي نبــات القــات وانتهــت‬\n      ‫املكاملــة وبالفعــل حضــرت للمتصــل يف شــقته يف نفــس يــوم االتصــال‬\n      ‫بعــد صــاة العشــاء وقمــت ببيعــه نبــات القــات احملظــور حيــث أعطانــي‬\n      ‫املشــتري مبلــغ ســبعمائة ريــال وســلمته مــا وزنه(‪)446‬أربعمائــة وســتة‬\n      ‫وأربعــون جرام ـ ًا مــن نبــات القــات احملظــور وبعدهــا حضــر رجــال‬\n\n\n‫‪127‬‬\n\f‫املكافحــة وقبضــوا علــي داخــل الشــقة ووجــدوا معــي عــدة حــزم مــن‬\n‫نبــات القــات احملظــور مجمــوع وزنهــا هو(‪)800‬ثمامنائــة جــرام وهــي‬\n‫تعــود لــي بقصــد االســتعمال كمــا أنــي أخبرتهــم بوجــود نبــات القــات‬\n‫احملظــور يف شــقتي فذهبــوا لشــقتي ووجــدوا عــدة حــزم خضــراء مــن‬\n‫نبــات القــات احملظــور بلــغ وزنهــا (‪)8916‬ثمانيــة االف وتســعمائة وســتة‬\n‫عشــر جرام ـ ًا وهــي تعــود لــي بقصــد االســتعمال فأنــا اســتعمل القــات‬\n‫احملظــور هــذا مــا حصــل ويوجــد لــدي ســابقة ترويــج القــات وأنــا نــادم‬\n‫علــى فعلــي هكــذا أجــاب بعــد ذلــك جــرى الرجــوع إلــى اللفــة رقــم(‪)9‬‬\n‫وتضمنــت محضــر التحريــز وجــاء فيــه وزن الكميــة املروجــة والكميــة‬\n‫احملــازة وهــو كمــا ذكــر املدعــي العــام يف دعــواه كمــا جــرى الرجــوع‬\n‫إلــى اللفــة رقم(‪)22‬وتضمنــت التقريــر الكيمــاوي الشــرعي وهــو كمــا‬\n‫ذكــر املدعــي العــام يف دعــواه بعــد ذلــك جــرى االطــاع علــى صــورة‬\n‫القــرار الشــرعي املرفــق لفــه رقم(‪)26‬الصــادر بحــق املدعــى عليــه برقــم‬\n‫‪ 55/4‬يف ‪1431/2/15‬ه ـ مــن احملكمــة اجلزائيــة ‪ ............‬حيــث ثبــت‬\n‫قيــام املدعــى عليــه ببيــع مائتــن وثالثــون جرام ـ ًا مــن القــات احملظــور‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه‬   ‫فبنـ ً‬\n‫بقيامــه ببيــع القــات احملظــور مســتخدم ًا هاتفــه اجلــوال يف ذلــك كمــا‬\n‫أقــر بحيازتــه القــات احملظــور بقصــد االســتعمال واســتعماله القــات‬\n‫احملظــور وحيــث إن للمدعــى عليــه ســابقة يف ترويــج القــات احملظــور‬\n‫كمــا أن الكميــه احملــازة كبيــرة وملــا جــاء يف محضــر التحريــز‬\n‫والتقريــر الكيمــاوي الشــرعي وملــا جــاء يف املادتــن الثالثــة والرابعــة‬\n               ‫مــن قــرار وزيــر الداخليــة رقــم ‪ 2057‬يف ‪1404/5/26‬ه ـ ‪.‬‬\n‫لــذا فقــد قــررت مــا يلــي أو ًال ثبــت لــدي قيــام املدعــى عليــه بترويــج مــا‬\n\n\n                                                                                        ‫‪128‬‬\n\f      ‫وزنــه (‪ )446‬أربعمائــة وســتة وأربعــون جرامـ ًا مــن نبــات القــات احملظــور‬\n      ‫عــن طريــق البيــع مببلــغ ســبعمائة ريــال وقــررت تعزيــره لقــاء ذلــك بســجنه‬\n      ‫مــدة ثــاث ســنوات اعتبــار ًا مــن تاريــخ إيقافــه وتغرميــه مبلــغ عشــرة االف‬\n      ‫ريــال ‪10000‬ثانيـ ًا ثبــت لــدي حيــازة املدعــى عليــه مــا وزنه(‪)9716‬تســعة‬\n      ‫االف وســبعمائة وســتة عشــر جرام ـ ًا مــن نبــات القــات احملظــور بقصــد‬\n      ‫االســتعمال وعقوبتــه التعزيريــة علــى ذلــك داخلــه يف عقوبتــه التعزيريــة‬\n      ‫املشــار لهــا بالفقــرة أو ًال ثالث ـ ًا ثبــت لــدي اســتعمال املدعــى عليــه لنبــات‬\n      ‫القــات احملظــور وقــررت تعزيــره لقــاء ذلــك بجلــده ســبعني جلــده علــى‬\n      ‫دفعتــن متســاويتني بينهمــا مــدة ال تقــل عــن عشــرة أيــام رابعـ ًا مصــادرة‬\n      ‫الهاتــف اجلــوال العائــد للمدعــى عليــه املســتخدم يف الترويــج وإســقاط‬\n      ‫الشــريحة وعــدم صرفهــا للمدعــى عليــه ومبــا تقــدم حكمــت وبعــرض‬\n      ‫احلكــم قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام مكتفيـ ًا مبــا قــدم يف‬\n      ‫الئحــة الدعــوى وأقفلــت اجللســة الســاعة الثانيــة عشــر إال ربــع وصلــى اهلل‬\n                                                              ‫وســلم علــى نبينــا محمــد ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة ‪ ............‬علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة ‪ ............‬برقــم‬\n      ‫‪ 34945720‬وتاريــخ ‪1434/4/28‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 34/1084974‬وتاريــخ ‪1434/5/4‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...‬املســجل برقــم ‪34193905‬‬\n      ‫وتاريــخ ‪1434/4/21‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ....‬يف قضيــة‬\n      ‫قــات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه؛‬\n      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n\n\n‫‪129‬‬\n\f‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                    ‫حــرر يف ‪1434/6/4‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                ‫‪130‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":124,"source_page_end":130,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"81a8c138f0d146e77b89a1331ed0e1a651ba8dd49cd647b1ee3a4f6a2fcba1df","normalized_text_hash":"511ae1b5746683d37e40da70c652e3742db408e85a6257a5897ef3994674e75a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p124-34193905"},{"id":"3f66795f-c49e-5fed-9117-47444ee64f1b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -إقرار املدعى عليه بالتعاطي -التعزير بالسجن واجللد -واإلبعاد عن الباد - سقوط جزء من عقوبة السجن بشرط حفظ أجزاء من القرآن","document_number":"34198765","case_number":"34178970","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/27","year":"1434","subject":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -إقرار املدعى عليه بالتعاطي -التعزير بالسجن واجللد -واإلبعاد عن الباد - سقوط جزء من عقوبة السجن بشرط حفظ أجزاء من القرآن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34198765 :‬تاريخه ‪1434/4/27:‬هـ‬\n                         ‫رقم القضية‪34178970:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34210699‬تاريخه‪1434/5/11 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة بقصــد الترويــج والتعاطــي ‪ -‬قــات ‪ -‬إقــرار املدعــى‬\n      ‫عليــه بالتعاطــي‪ -‬التعزيــر بالســجن واجللــد ‪ -‬واإلبعــاد عــن البــاد ‪-‬‬\n      ‫ســقوط جــزء مــن عقوبــة الســجن بشــرط حفــظ أجــزاء مــن القــرآن‬\n                                                                        ‫الكــرمي‪.‬‬\n\n\n\n\n      ‫‪ -1‬املــادة الرابعــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬يف ‪1374/2/1‬ه‬\n      ‫املعــدل بقــراري وزيــر الداخليــة رقــم(‪ )2057‬لعــام ‪ 1404‬ه ـ ورقــم ‪3818‬‬\n                                                                ‫لعــام ‪1410‬ه ـ ‪.‬‬\n                      ‫‪ -2‬األمر السامي الكرمي رقم (‪ )59633‬يف ‪1433/12/9‬هـ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة القــات بقصــد الترويــج‬\n      ‫والتعاطــي وطلــب إثبــات مــا أســند إليــه واحلكــم بتعزيــره وفــق النظــام‪،‬‬\n      ‫حيــث قبــض علــى املدعــى عليــه أثنــاء قيادتــه الســيارة وبتفتيشــه عثــر‬\n      ‫بحوزتــه علــى نبــات القــات وأثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫إيجابيــة العينــة لنبــات القــات احملظــور ‪ .‬مصادقــة املدعــى عليــه علــى‬\n      ‫التعاطــي وليــس الترويــج‪ ،‬وملــا كانــت بينــة املدعــي العــام للترويــج غيــر‬\n      ‫موصلــة ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه‬\n\n‫‪131‬‬\n\f‫بالســجن ســنة وســقوط ثالثــة أشــهر مــن محكوميتــه عنــد حفظــه ثالثــة‬\n‫أجــزاء وجلــده مائــة وخمســن جلــدة مفرقــة علــى دفعــات مقــدار كل‬\n‫دفعــة خمســون جلــدة لقــاء شــبهة الترويــج وإبعــاده عــن اململكــة بعــد‬\n‫انتهــاء محكوميتــه وقنــع املدعــى عليــه واعتــرض املدعــي العــام بــدون‬\n                     ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬    ‫الئحــة ُ‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n‫‪ .....‬القاضــي يف احملكمــة اجلزائيــة بجــازان وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم ‪34178970‬‬\n‫وتاريــخ ‪1434/04/20‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34955837‬وتاريــخ‬\n‫‪1434/04/20‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/04/27‬ه ـ افتتحــت‬\n‫اجللســة الســاعة العاشــرة والنصــف صباحـ ًا وفيهــا حضــر املدعــي العــام‬\n‫‪.....‬املعمــد بالعمــل مبوجــب خطــاب رقــم ‪.....‬وتاريــخ ‪1433/03/22‬ه ـ‬\n‫وحضــر املدعــى عليــه ‪.....‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n‫ا يف دعــواه أنــه‬\n                 ‫(‪ ).....‬وتاريــخ ‪1423/7/18‬ه ـ وادعــى املدعــي العــام قائـ ً‬\n‫بتاريــخ ‪1434/03/8‬ه ـ وأثنــاء قيــام إحــدى دوريــات مركــز املجاهديــن‬\n‫بواجبهــا امليدانــي املعتــاد وأثنــاء تواجــد الفرقــة باملوقــع املســمى مثلــث‬\n‫هــروب مت القبــض علــى املدعــى عليــه أثنــاء قيادتــه لســيارة مــن نــوع‬\n‫صالــون صنــع ‪1998‬م حتمــل اللوحــة رقــم (‪ ).....‬وبتفتيشــه عثــر بحوزتــه‬\n‫علــى كميــة مــن نبــات القــات احملظــور بلــغ وزنهــا خمســة وعشــرون‬\n‫كيلــو جرام ـ ًا أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ ).....‬بتاريــخ‬\n‫‪1434/03/17‬ه ـ إيجابيــة العينــة للقــات احملظــور وباســتجواب املدعــى‬\n\n                                                                                     ‫‪132‬‬\n\f      ‫عليــه أقــر بحيازتــه للكميــة املضبوطــة من نبات القات احملظور وذك ــر‬\n      ‫بأنهــا تعـ ــود لــه وغرضــه منهــا التعاطــي وأنــه حصــل عليهــا مــن شــخص‬\n      ‫مينــي ال يعرفــه مببلــغ ســتمائة ريــال وصــادق علــى أقوالــه حتقيق ـ ًا وقــد‬\n      ‫أســفر التحقيــق معــه عــن توجيــه االتهــام إليــه بحيــازة مــا وزنــه خمســة‬\n      ‫وعشــرون كيلــو جرامـ ًا مــن القــات احملظــور بقصــد الترويــج والتعاطــي‬\n      ‫وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة وحيــث أن مــا‬\n      ‫أقــدم عليــه املدعــى عليــه فعــل محــرم شــرع ًا ومجــرم نظام ـ ًا مبوجــب‬\n      ‫قــرار مجلــس الــوزراء رقــم (‪ )11‬يف ‪1374/2/1‬ه ـ ومــا حلــق بــه مــن‬\n      ‫تعديــات لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره‬\n      ‫يف ضــوء املادتــن (الثالثــة) و (الرابعــة) مــن القــرار الــوزاري املشــار إليــه‬\n      ‫إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/09‬ه ـ‬\n      ‫واحلكــم بإبعــاده إلــى بــاده وذلــك اســتناد ًا لتعميــم ســمو وزيــر الداخليــة‬\n      ‫رقــم ‪ 69935‬وتاريــخ ‪1433/06/18‬ه ـ وبســؤال املدعــى عليــه عمــا جــاء‬\n      ‫ا مــا ذكــره املدعــي العــام مــن اتهامــي‬  ‫بدعــوى املدعــي العــام أجــاب قائـ ً‬\n      ‫بحيــازة مــا وزنــه خمســة وعشــرون كيلــو جرام ـ ًا مــن القــات احملظــور‬\n      ‫بقصــد الترويــج والتعاطــي فهــذا غيــر صحيــح والصحيــح أنهــا للتعاطــي‬\n      ‫فقــط حيــث اشــتريتها مببلــغ قــدره ســتمائة ريــال هكــذا أجــاب ثــم جرى‬\n      ‫ســؤال املدعــي العــام هــل لديــه بينــة علــى كــون املدعــى عليــه قــد حــاز‬\n      ‫ا بينتــي علــى ذلــك هــي كبــر‬    ‫الكميــة لغــرض الترويــج فأجــاب قائ ـ ً‬\n      ‫حجــم الكميــة هكــذا أجــاب وبعــد ســماع الدعــوى واإلجابــة جــرى‬\n      ‫منــي دراســة األوراق واالطــاع علــى محضــر القبــض املرفــق باملعاملــة‬\n      ‫فوجدتــه يتضمــن القبــض علــى املدعــى عليــه وبحوزتــه الكميــة‬\n      ‫املذكــورة يف الدعــوى مــن القــات احملظــور ولــم أجــد مــا يثبــت حيازتــه‬\n\n\n‫‪133‬‬\n\f‫للكميــة لغــرض الترويــج ثــم جــرى االطــاع علــى صحيفــة ســوابق‬\n‫املدعــى عليــه فوجــدت أنــه ال توجــد ســوابق مســجلة عليــه ثــم جــرى‬\n‫االطــاع علــى التقريــر الكيميائــي الشــرعي املرفــق باملعاملــة فوجدتــه‬\n‫ـاء علــى ما تقدم مــن الدعوى‬  ‫يتضمــن إيجابيــة العينــة للقــات احملظــور فبنـ ً‬\n‫واإلجابــة وحيــث أقــر املدعــى عليــه بحيازتــه للكميــة املذكــورة يف‬\n‫الدعــوى مــن القــات احملظــور بقصــد التعاطــي وأنكــر الترويــج وحيــث‬\n‫أن بينــة املدعــي العــام غيــر موصلــة علــى كــون املدعــى عليــه قــد حــاز‬\n‫الكميــة لغــرض الترويــج وذلــك لعــدم كفايــة األدلــة ضــده وحيــث‬\n‫توجهــت شــبهة الترويــج ضــد املدعــى عليــه وذلــك نظــر ًا لكبــر حجــم‬\n‫الكميــة وحيــث ال توجــد ســوابق مســجلة عليــه وحيــث أثبــت التقريــر‬\n‫الكيميائــي الشــرعي إيجابيــة العينــة للقــات احملظــور ولــكل مــا تقــدم‬\n                                   ‫فقــد حكمــت مبــا يلــي أو ًال ‪ /‬ثبــت لـ ّ‬\n‫ـدي إدانــة املدعــى عليــه بحيــازة‬\n‫مــا وزنــه خمســة وعشــرون كيلــو جرام ـ ًا مــن القــات احملظــور بقصــد‬\n‫التعاطــي ومبوجــب ذلــك صرفــت النظــر عــن طلــب املدعــي العــام بتعزيــر‬\n‫املدعــى عليــه وفقـ ًا للمــادة الثالثــة وذلــك لعــدم ثبــوت الترويــج لــدي ثانيـاً‪/‬‬\n‫حكمــت عليــه بالســجن ملــدة ســنة تبــدأ مــن تاريــخ دخولــه الســجن علــى‬\n‫ذمــة هــذه القضيــة وذلــك اســتناد ًا للمادة الرابعة من قــرار مجلس الوزراء‬\n‫رقــم (‪ )11‬يف ‪1374/2/1‬ه ـ املعــدل بقــراري ســمو وزيــر الداخليــة رقــم‬\n‫(‪ )2057‬يف ‪1404/5/26‬ه ـ ورقــم (‪ )3818‬يف ‪1410/9/28‬ه ـ إنفــاذ ًا‬\n‫لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬هـ ويســقط‬\n‫عــن املدعــى عليــه ثالثــة أشــهر مــن محكوميتــه وذلــك عنــد حفظــه‬\n‫لثالثــة أجــزاء مــن القــرآن حفظـ ًا متقنـ ًا بعــد اختبــار يجــرى لــه مــن قبــل‬\n‫اجلهــة املختصــة ثالث ـ ًا ‪ /‬حكمــت بجلــده مائــة وخمســن جلــدة مفرقــة‬\n\n\n                                                                                           ‫‪134‬‬\n\f      ‫علــى دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة واألخــرى مــدة‬\n      ‫ال تقــل عــن خمســة عشــر يوم ـ ًا وذلــك لقــاء توجــه شــبهة الترويــج ضــده‬\n      ‫نظــر ًا لكبــر حجــم الكميــة رابع ـ ًا ‪ /‬حكمــت بإبعــاده عــن اململكــة‬\n      ‫بعــد انتهــاء محكوميتــه وذلــك اســتناد ًا للمــادة الرابعــة مــن قــرار مجلــس‬\n      ‫الــوزراء رقــم (‪ )11‬يف ‪1374/2/1‬ه ـ املعــدل بقراري ســمو وزير الداخلية‬\n      ‫رقــم (‪ )2057‬يف ‪1404/5/26‬ه ـ ورقــم (‪ )3818‬يف ‪1410/9/28‬ه ـ‬\n      ‫إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ‬\n      ‫وبعــرض احلكــم علــى املدعــى عل ــيه قــرر القناعــة باحلكــم كمــا قــرر‬\n      ‫املدعــي العــام االعتــراض علــى احلكــم بــدون تقــدمي الئحــة اعتراضيــة‬\n      ‫عليــه قــررت رفــع املعاملــة حملكمــة االســتئناف حســب التعليمــات‬\n      ‫وقــد جــرى النطــق باحلكــم يف الســاعة احلاديــة عشــرة صباح ـ ًا بتاريــخ‬\n      ‫‪1434/04/27‬ه ـ وصلــى اهلل علــى س ــيدنا محمــد وآلــه وصحبــه وســلم‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائية بجازان برقــم ‪34955837‬‬\n      ‫وتاريــخ ‪1434/4/29‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضي‬\n      ‫باحملكمــة الشــيخ ‪ .....‬برقــم ‪ 34198765‬وتاريــخ ‪1434/4/27‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد ‪ -.....‬مينــي اجلنســية ‪ -‬يف قضيــة‬\n      ‫( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n      ‫املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                                  ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n‫‪135‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":131,"source_page_end":135,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"698bfac323f4bb814652e6ab0cd8f63e2c08c7c529ea921373cb4972e391362d","normalized_text_hash":"a124941aca83a398194146665552236a8c08e17ae99c071de1cc5d5548a3a9fe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p131-34198765"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
